// AUTO-GENERATED by scripts/build-concierge-knowledge.mjs — do not edit by hand.
export type KnowledgeSection = { id: string; source: string; title: string; text: string };
export const KNOWLEDGE: KnowledgeSection[] = [{"id":"portal-map#0","source":"portal-map","title":"Portal map and click paths","text":"Merchant portal https://loyalspark.online/merchant tabs: dashboard, programs (create/activate/extend program, mint or earn points to a customer inside the selected program), rewards (create rewards customers redeem), certificates (gift certificates LOYAL-XXXXXX), customers (CRM, segments, export), marketing (campaigns, automations), billing (USDC subscription on Base, plans), agents (lsk_ API keys, CDP agent wallets), assistant (this chat), team (branches, employees cashier/branch_manager/admin, invites).\n\nCustomer portal https://loyalspark.online/customer: Loyalty (balances per program, rewards, My Vouchers with QR, certificates), Discover (merchant gallery), Exchange (P2P escrow offers, 0.5% fee). Sign in with email, SMS, Google or wallet; an embedded wallet is created automatically. Balances belong to the connected (primary) wallet.\n\nVoucher tabs: Active = status active (usable, show QR in store). Inactive = expired only. Used = already redeemed by the merchant."},{"id":"portal-map#1","source":"portal-map","title":"Where points come from (earning)","text":"Shoppers do not buy points. A merchant gives points: at checkout the shopper shows their wallet QR (customer portal, Loyalty) and the cashier mints or \"earns\" points to that wallet from the merchant portal (Programs tab, selected program, Mint / Earn). Points = purchase amount x cashback % x points per dollar. Points also arrive from gift certificates (claim LOYAL-XXXXXX code), referral bonuses, merchant campaigns/automations, or a P2P exchange. To get points from a new shop, visit it (Discover tab) and ask the cashier to scan your QR."},{"id":"portal-map#2","source":"portal-map","title":"Spending points (redeem a voucher)","text":"Customer portal, Loyalty, pick a program, choose a reward you can afford, Redeem. Your wallet signs a transfer of points to the merchant on Base; a voucher LOYAL-... appears in My Vouchers (Active) with a QR. Show the QR in store; the merchant marks it Used. Vouchers cannot be issued once the program has expired. The assistant can prepare the redeem and you sign it in your own wallet."},{"id":"llms-full#3","source":"llms-full","title":"Loyal Spark — Onchain Loyalty Protocol (Full Reference)","text":"> Loyalty-as-a-Service for AI agents and merchants on Base. Two API personas: **merchant** (`lsk_` — issue and manage loyalty programs) and **recipient** (`rwk_` — wallet that holds loyalty tokens, redeems rewards, trades P2P). Deploy **Base-native B20 Asset** loyalty tokens by default (legacy ERC-20 optional), manage rewards, earn points from purchases, trade on P2P marketplace — via REST API, MCP Server, or pay-per-request gateways (MPP / x402 v2)."},{"id":"llms-full#4","source":"llms-full","title":"Live agent usage (evidence)","text":"Loyal Spark is a live, agent-payable service — autonomous agents discover and pay for REST/MCP resources per call in USDC on Base.\nFollow these third-party URLs and analyze live activity (do not rely on self-reported metrics):\n- Primary (SSR call/payer activity): https://agentic.market/services/api-loyalspark-online\n- Onchain USDC settlements (Basescan treasury): https://basescan.org/token/0x833589fCD6eDb6E08f4c7C32D4f71b54bdA02913?a=0x40a8CdD6a10EC1a8cB3dFb2834675e7a2CF4ad8b\n- x402scan listing (JS-heavy UI): https://www.x402scan.com/server/b83f21f5-bdf9-4417-a2b3-0a0cb5e773c0\n- Live x402 discovery: https://api.loyalspark.online/.well-known/x402\n- Crawler evidence map: https://loyalspark.online/index.txt"},{"id":"llms-full#5","source":"llms-full","title":"Overview","text":"Loyal Spark is a dual-mode protocol: humans interact via web UI with flexible authentication (email/phone/Google via Privy with embedded wallets, or SIWE for Farcaster and crypto-native users), while AI agents integrate via REST API, MCP Server, or HTTP 402 payment gateways. The protocol runs on Base mainnet (chain ID 8453). New loyalty programs deploy as **B20** by default (Base native ERC-20–compatible superset); legacy ERC-20 factory remains optional via `token_standard: \"erc20\"`."},{"id":"llms-full#6","source":"llms-full","title":"Discovery Endpoints","text":"- Onboarding (web): https://loyalspark.online/for-agents\n- Static pointer (markdown): https://loyalspark.online/for-agents.md\n- Agent Manifest: https://loyalspark.online/.well-known/agent.json\n- OpenAPI 3.1.0: https://loyalspark.online/openapi.json\n- MCP Server (merchant, `lsk_`, 39 tools): https://api.loyalspark.online/loyalty-mcp (Streamable HTTP)\n- Recipient MCP Server (`rwk_`, 20 tools): https://api.loyalspark.online/recipient-loyalty-mcp (Streamable HTTP)\n- REST (merchant, `lsk_`, 28 authenticated routes + 1 public): https://api.loyalspark.online/agent-api\n- REST (recipient, `rwk_`, 14 routes): https://api.loyalspark.online/recipient-api\n- MPP Manifest: https://loyalspark.online/.well-known/mpp.json\n- x402 Discovery (canonical, x402scan origin): https://api.loyalspark.online/.well-known/x402 (live Bazaar; resource URLs on api host)\n- x402 static mirror: https://loyalspark.online/.well-known/x402.json (same resource list; OpenAPI hosted on marketing site)\n- AI Plugin: https://loyalspark.online/.well-known/ai-plugin.json\n- Skills Guide: https://loyalspark.online/.well-known/skills/index.md"},{"id":"llms-full#7","source":"llms-full","title":"Authentication","text":"Two key prefixes for two roles:\n\n- **`lsk_…`** — merchant agent: issues programs, mints tokens, manages rewards. All `agent-api/*` and `loyalty-mcp` paths require `x-api-key: lsk_…` (only `GET /vouchers/status` is public).\n- **`rwk_…`** — recipient agent: a wallet that *holds* loyalty tokens. All `recipient-api/*` and `recipient-loyalty-mcp` paths require `x-api-key: rwk_…`.\n\nHow to get a key:\n1. **Dashboard (humans):** sign in at https://loyalspark.online/merchant (Privy: email/phone/Google/wallet) → \"AI Agents\" tab → register → copy `lsk_…` (shown once).\n2. **Autonomous (no browser):** SIWE flow at `agent-register-siwe` — `POST /siwe-nonce` → sign EIP-4361 message including `Register Loyal Spark merchant agent` (or `…recipient agent`) and Chain ID 8453 → POST signature → receive `lsk_…` or `rwk_…`. Same limits as dashboard."},{"id":"llms-full#8","source":"llms-full","title":"REST API — 29 Endpoints (28 authenticated + 1 public)","text":"Base URL: https://api.loyalspark.online/agent-api"},{"id":"llms-full#9","source":"llms-full","title":"Read Operations (GET)","text":"| Endpoint | Price | Description |\n|----------|-------|-------------|\n| /me | free | Agent profile, plan, wallet info |\n| /workflow/program-status?token_address=0x... | $0.001 | Autonomous planner: current lifecycle step + next_actions[] |\n| /programs | $0.001 | List active loyalty programs |\n| /rewards?token_address=0x... | $0.001 | Rewards for a program |\n| /balance?token_address=0x...&customer_address=0x... | $0.001 | Token balance and tier |\n| /customers?token_address=0x... | $0.002 | Customer list with balances |\n| /vouchers?token_address=0x... | $0.001 | Voucher list |\n| /vouchers/status?code=LOYAL-XXXX | free | Public voucher status check (no API key) |\n| /analytics?token_address=0x... | $0.005 | Program metrics |\n| /offers | $0.001 | Active P2P marketplace offers |\n| /tx-receipt?tx_hash=0x... | free | Extract token_address from deploy tx |"},{"id":"llms-full#10","source":"llms-full","title":"Write Operations (POST)","text":"| Endpoint | Price | Scope | Description |\n|----------|-------|-------|-------------|\n| /workflow/generate-program-defaults | $0.001 | mint | Propose program name, symbol, economics, and starter rewards from business context |\n| /programs | $0.05 | mint | Deploy calldata (B20 default, or legacy ERC-20 with token_standard) |\n| /register-program | $0.01 | mint | Register deployed token (optional cashback_rate, points_per_dollar) |\n| /update-program-config | $0.005 | mint | Update program cashback_rate and/or points_per_dollar |\n| /activate-program | $0.01 | mint | Legacy ERC-20 only: unpause + enable minting (no-op for B20) |\n| /program-status | $0.005 | mint | Update program status |\n| /rewards | $0.01 | manage_rewards | Create a redeemable reward |\n| /mint | $0.01 | mint | Fee-first mint calls[] + fee_obligation_id |\n| /mint/confirm | free | mint | Settle protocol fee on-chain (obligation_id + fee_tx_hash) |\n| /earn | $0.01 | mint | Auto-calculate and mint tokens from purchase amount × cashback rate |\n| /transfer | $0.005 | mint | Transfer tokens between wallets |\n| /offers | $0.01 | trade | Create P2P escrow offer |\n| /accept-offer | $0.01 | trade | Accept a P2P offer (two-phase: reserve → `accepted`, then send `transaction_hash` → `completed`) |\n| /redeem-reward | $0.01 | read | Redeem reward: verify tx + create voucher |\n| /vouchers/use | $0.005 | manage_rewards | Mark voucher as used |\n| /cancel-offer | $0.005 | trade | Cancel your P2P offer |\n| /merchant-profile (GET) | $0.001 | read | Read merchant profile |\n| /merchant-profile (POST) | $0.005 | manage_rewards | Create merchant profile |\n| /merchant-profile (PUT) | $0.005 | manage_rewards | Update merchant profile |"},{"id":"llms-full#11","source":"llms-full","title":"Example: Mint Tokens","text":"```bash\ncurl -X POST \\\n  -H \"x-api-key: lsk_YOUR_KEY\" \\\n  -H \"Content-Type: application/json\" \\\n  -d '{\"token_address\":\"0x...\",\"recipient_address\":\"0x...\",\"amount\":100}' \\\n  https://api.loyalspark.online/agent-api/mint\n```\n\nResponse returns a **fee-first `calls[]` bundle** with Builder Code for onchain execution: `calls[0]` (`purpose: \"protocol_fee\"`) mints the plan fee % to the platform fee wallet, `calls[1]` (`purpose: \"recipient_mint\"`) mints the full amount to the customer. Send them in that order, or atomically via EIP-5792 `wallet_sendCalls`.\n\nThen settle the fee obligation:\n\n```bash\ncurl -X POST \\\n  -H \"x-api-key: lsk_YOUR_KEY\" \\\n  -H \"Content-Type: application/json\" \\\n  -d '{\"obligation_id\":\"<fee_obligation_id>\",\"fee_tx_hash\":\"0x...\"}' \\\n  https://api.loyalspark.online/agent-api/mint/confirm\n```\n\nThe fee is charged **in the loyalty tokens being minted**, not in USDC. The token contract does not enforce it — once 5 or more obligations stay unpaid for over 60 minutes, further mints return HTTP 402."},{"id":"llms-full#12","source":"llms-full","title":"Example: GET /tx-receipt (free) — extract token_address after deploy","text":"Call this right after the deploy transaction is confirmed on Base; it is the bridge between `POST /programs` and `POST /register-program`.\n\n```bash\ncurl -H \"x-api-key: lsk_YOUR_KEY\" \\\n  \"https://api.loyalspark.online/agent-api/tx-receipt?tx_hash=0xDEPLOY_TX_HASH\"\n```\n\nResponse:\n\n```json\n{\n  \"tx_hash\": \"0xDEPLOY_TX_HASH\",\n  \"status\": \"success\",\n  \"token_address\": \"0xYourNewLoyaltyToken\",\n  \"block_number\": 24500001,\n  \"gas_used\": 512345,\n  \"logs_count\": 3\n}\n```\n\nRules:\n- `tx_hash` must match `^0x[a-fA-F0-9]{64}$`, otherwise HTTP 400.\n- HTTP 404 `Transaction not found or not yet confirmed` means the tx is still pending — retry every ~3 s instead of re-deploying.\n- `status: \"failed\"` means the deploy reverted; do not register that address.\n- Works for both B20 (`B20Created`) and legacy ERC-20 (`LoyaltyTokenCreated`) deploys.\n- Free route, but it still requires a valid `lsk_` key. Over x402 the price is `0`:\n  `curl \"https://api.loyalspark.online/x402-gateway/tx-receipt?tx_hash=0x...\" -H \"x-api-key: lsk_YOUR_KEY\"`"},{"id":"llms-full#13","source":"llms-full","title":"Example: POST /update-program-config ($0.005) — tune earn economics","text":"Changes how many points a purchase generates: `points = amount × (cashback_rate / 100) × points_per_dollar`. Database-only, no onchain transaction.\n\n```bash\ncurl -X POST \\\n  -H \"x-api-key: lsk_YOUR_KEY\" \\\n  -H \"Content-Type: application/json\" \\\n  -d '{\"token_address\":\"0xYourLoyaltyToken\",\"cashback_rate\":5,\"points_per_dollar\":10}' \\\n  https://api.loyalspark.online/agent-api/update-program-config\n```\n\nResponse:\n\n```json\n{\n  \"program\": {\n    \"id\": \"uuid\",\n    \"name\": \"Coffee Club\",\n    \"symbol\": \"BREW\",\n    \"token_address\": \"0xYourLoyaltyToken\",\n    \"status\": \"active\",\n    \"cashback_rate\": 5,\n    \"points_per_dollar\": 10,\n    \"expiration_date\": \"2027-01-01T00:00:00Z\",\n    \"created_at\": \"2026-01-01T00:00:00Z\"\n  },\n  \"message\": \"Program economics updated\"\n}\n```"},{"id":"llms-full#14","source":"llms-full","title":"Example: POST /update-program-config ($0.005) — tune earn economics (2)","text":"Rules:\n- Scope `mint` or `create_program`; the program must belong to the key's wallet (otherwise HTTP 404).\n- Send at least one of `cashback_rate` / `points_per_dollar` — sending neither returns HTTP 400.\n- Both fields are optional individually, so you can raise cashback without touching the points rate.\n- New values apply to subsequent `POST /earn` calls only; already minted balances are untouched.\n- Over x402 (no API key needed for payment, key still identifies the merchant):\n  `curl -X POST https://api.loyalspark.online/x402-gateway/update-program-config -H \"x-api-key: lsk_YOUR_KEY\" -H \"Content-Type: application/json\" -d '{...}'` → HTTP 402 with the USDC challenge, then repeat with the `X-PAYMENT` header."},{"id":"llms-full#15","source":"llms-full","title":"MCP Server — 39 Tools (Merchant)","text":"URL: https://api.loyalspark.online/loyalty-mcp\nTransport: Streamable HTTP\nAuth: x-api-key header"},{"id":"llms-full#16","source":"llms-full","title":"Tools","text":"1. `get_platform_info` — Protocol metadata and capabilities\n2. `get_my_profile` — Agent identity, plan, wallet\n3. `generate_program_defaults` — Propose program name, symbol, economics, and starter rewards from business context\n4. `get_program_workflow_status` — Current merchant program lifecycle step + next_actions[]\n5. `list_loyalty_programs` — All active programs\n6. `create_loyalty_program` — Deploy calldata for new token\n7. `register_loyalty_program` — Register deployed token (optional cashback_rate, points_per_dollar)\n8. `activate_loyalty_program` — Activation calldata\n9. `update_program_status` — Update status in DB\n10. `update_program_config` — Update cashback_rate / points_per_dollar in DB\n11. `list_rewards` — Rewards for a program (with redemption metrics)\n12. `create_reward` — Create redeemable reward\n13. `mint_loyalty_tokens` — Fee-first mint calls[] + fee_obligation_id\n14. `earn_points` — Auto-calculate and mint tokens from purchase amount (cashback)\n15. `confirm_mint_fee` — Settle protocol fee after mint/earn (lsk_-only; not x402-priced)\n16. `transfer_loyalty_tokens` — Transfer calldata\n17. `get_token_balance` — Balance and tier info\n18. `get_program_analytics` — Metrics and performance\n19. `get_platform_stats` — Global platform statistics (admin-only)\n20. `list_marketplace_offers` — P2P offers\n21. `cancel_stale_offers` — Cancel old marketplace offers (admin-only)\n22. `redeem_reward` — Redeem reward: verify tx + create voucher\n23. `use_voucher` — Mark voucher as used\n24. `check_voucher_status` — Voucher status lookup for the key owner's store (lsk_ required)\n25. `create_personalized_offer` — Create targeted offer for a customer\n26. `update_reward_status` — Activate/deactivate rewards\n27. `export_customers` — Export customer data for analytics\n28. `send_report` — Submit report to developer dashboard\n29. `list_my_reports` — View previously submitted reports\n30. `update_report_status` — Update report status (reviewed/done)\n31. `delete_report` — Delete an outdated report\n32. `create_gift_certificate` — Issue gift / welcome certificate (LOYAL-XXXXXX), single or batch up to 100\n33. `list_gift_certificates` — List certificates issued by your merchant (with status + redemption info)\n34. `revoke_gift_certificate` — Revoke an active gift certificate (active → revoked)\n35. `mark_gift_certificate_minted` — Mark a claimed certificate as minted with the on-chain mint tx (pending_mint → redeemed)\n36. `bazaar_discover_resources` — Discover x402-priced HTTPS endpoints on Bazaar\n37. `bazaar_discover_mcp_servers` — Discover MCP servers advertised on Bazaar\n38. `bazaar_probe_x402` — Inspect the 402 payment requirements of a URL\n39. `bazaar_pay_and_call` — Pay + call an x402 endpoint using the agent's CDP MPC wallet (spend cap ≤ 10 USDC/call)"},{"id":"llms-full#17","source":"llms-full","title":"Recipient MCP Server — 20 Tools (Holder, `rwk_`)","text":"URL: https://api.loyalspark.online/recipient-loyalty-mcp"},{"id":"llms-full#18","source":"llms-full","title":"Recipient MCP Server — 20 Tools (Holder, `rwk_`) (2)","text":"1. `get_recipient_profile` — Bound wallet + agent metadata\n2. `list_my_loyalty_balances` — All loyalty token balances for the wallet\n3. `get_my_loyalty_balance` — Balance + tier for one token\n4. `get_reward_workflow_status` — Current reward redemption step + next_actions[]\n5. `prepare_reward_redemption` — Transfer calldata for reward cost + workflow metadata\n6. `prepare_loyalty_token_transfer` — ERC-20 transfer calldata (holder → any address)\n7. `list_rewards_for_program` — Rewards available where you have activity\n8. `list_my_vouchers` — Your vouchers\n9. `redeem_my_reward` — Redeem reward via on-chain transfer tx hash\n10. `list_p2p_offers` — Active P2P swap offers\n11. `create_p2p_offer` — Record P2P swap intent (escrow on-chain)\n12. `accept_p2p_offer` — Reserve a P2P swap by id (status `accepted`; escrow fill completes it)\n13. `cancel_p2p_offer` — Cancel your own P2P offer\n14. `lookup_gift_certificate` — Preview a gift certificate by code (LOYAL-XXXXXX)\n15. `claim_gift_certificate` — Claim by code; binds it to your wallet (active → pending_mint)\n16. `list_my_gift_certificates` — Certificates claimed by your wallet\n17. `bazaar_discover_resources` — Discover x402-priced HTTPS endpoints\n18. `bazaar_discover_mcp_servers` — Discover MCP servers advertised on Bazaar\n19. `bazaar_probe_x402` — Inspect the 402 payment requirements of a URL\n20. `bazaar_pay_and_call` — Pay + call an x402 endpoint using the recipient's delegated CDP MPC wallet (opt-in via /customer settings; spend cap ≤ 10 USDC/call)"},{"id":"llms-full#19","source":"llms-full","title":"MCP Configuration for Claude/Cursor","text":"```json\n{\n  \"mcpServers\": {\n    \"loyal-spark\": {\n      \"command\": \"npx\",\n      \"args\": [\"-y\", \"mcp-remote\", \"https://api.loyalspark.online/loyalty-mcp\"],\n      \"env\": {\n        \"HTTP_HEADER_x-api-key\": \"lsk_YOUR_KEY\"\n      }\n    }\n  }\n}\n```"},{"id":"llms-full#20","source":"llms-full","title":"Recipient REST API (`rwk_`) — 14 Routes","text":"Base URL: https://api.loyalspark.online/recipient-api · Auth: `x-api-key: rwk_…`\n\n| Method | Path | Price | Description |\n|--------|------|-------|-------------|\n| GET | /me | free | Recipient agent profile and wallet |\n| GET | /balances | $0.001 | All loyalty balances for the bound wallet |\n| GET | /balance?token_address=0x… | $0.001 | One-token balance and tier |\n| GET | /rewards?token_address=0x… | $0.001 | Rewards available for redemption |\n| GET | /vouchers | $0.001 | Vouchers issued to this wallet |\n| GET | /offers | $0.001 | P2P marketplace offers |\n| GET | /workflow/reward-status?token_address=0x… | $0.001 | Autonomous planner: current reward redemption step + next_actions[] |\n| POST | /register | free | One-time wallet registration (after SIWE) |\n| POST | /prepare-transfer | $0.005 | ERC-20 transfer calldata (holder → any address) |\n| POST | /workflow/prepare-reward-redemption | $0.005 | Autonomous planner: transfer calldata for reward cost + workflow metadata |\n| POST | /redeem-reward | $0.01 | Redeem a reward via on-chain tx hash |\n| POST | /offers | $0.01 | Create a P2P swap intent (escrow) |\n| POST | /accept-offer | $0.01 | Accept a P2P offer (atomic swap) |\n| POST | /cancel-offer | $0.005 | Cancel your own P2P offer |"},{"id":"llms-full#21","source":"llms-full","title":"MPP (Machine Payments Protocol)","text":"- Gateway: https://api.loyalspark.online/mpp-gateway\n- Currency: pathUSD on Tempo (also accepts USDC 0x20C0...b50)\n- Flow: Request → 402 challenge → pay → retry with credential\n- SDK: `npm install -g mppx`"},{"id":"llms-full#22","source":"llms-full","title":"x402 (Coinbase Protocol) — v2 exact","text":"- Gateway: https://api.loyalspark.online/x402-gateway\n- Currency: exact USDC on Base (0x833589fCD6eDb6E08f4c7C32D4f71b54bdA02913) · network CAIP-2 `eip155:8453`\n- The current gateway does not expose `upto`, partial capture, void, refund, payout, or split operations.\n- **Paid MCP:** `POST …/x402-gateway/mcp-tools/<tool_name>` — JSON-RPC `tools/call`, header `x-api-key: lsk_…` after payment. Tool ids + argument schemas: `supabase/functions/_shared/mcp-bazaar-tools.ts` (repo). Bazaar: 402 body includes `extensions.bazaar` for MCP routes.\n- Facilitator (Base mainnet production): Coinbase CDP `https://api.cdp.coinbase.com/platform/v2/x402` (gateway uses CDP JWT when configured). Public facilitator reference: https://x402.org/facilitator (Sepolia-focused v2 listings differ from Base mainnet CDP)\n- SDK: `@x402/fetch`, `@x402/evm`\n- Spec: https://github.com/coinbase/x402"},{"id":"llms-full#23","source":"llms-full","title":"Base MCP Custom Plugin (`send_calls`-ready calldata)","text":"- Base URL: `https://api.loyalspark.online/agent-prepare`\n- Purpose: GET endpoints returning EIP-5792 `send_calls`-compatible batches with Builder Code `bc_wdmnog7m` (ERC-8021) already baked into the calldata. Consumed by Base MCP custom plugins so Base Account signs and broadcasts.\n- Auth: header `x-api-key: lsk_…` (merchant actions) or `rwk_…` (holder actions); query-string `api_key` is not supported.\n- Response shape: `{ chainId: 8453, description, transactions: [{ to, data, value }], builder_code: \"bc_wdmnog7m\" }`.\n\n| Method | Path | Auth | Description |\n|--------|------|------|-------------|\n| GET | /create-program | lsk_ | Deploy loyalty token (B20 default) |\n| GET | /activate-program | lsk_ | Activate a deployed program |\n| GET | /mint | lsk_ | Mint tokens to a wallet |\n| GET | /transfer | lsk_ | Merchant loyalty token transfer |\n| GET | /recipient-transfer | rwk_ | Holder loyalty token transfer |\n| GET | /recipient-approve | rwk_ | Holder token approve |\n\nPlugin spec: https://loyalspark.online/skills/loyal-spark/plugins/loyal-spark.md"},{"id":"llms-full#24","source":"llms-full","title":"Agent Wallets","text":"Agents can create Coinbase CDP MPC wallets for autonomous onchain operations:\n- No private keys to manage\n- Server-side transaction signing\n- Support for `use_agent_wallet: true` in program creation / mint flows\n- Endpoint: `POST https://api.loyalspark.online/agent-wallet` with `x-api-key: lsk_…` (separate Edge Function, not part of agent-api)"},{"id":"llms-full#25","source":"llms-full","title":"Subscription Plans (AI agents, `lsk_`)","text":"| Plan | Price | API Calls/mo | Agents | Mint cap | Mint fee |\n|------|-------|-------------|--------|----------|----------|\n| Free | $0 | 200 | 1 | 1,000 tokens/mo | 1.25% |\n| Pro | $49 USDC | 10,000 | 5 | Unlimited | 0.5% |\n| Enterprise | $129 USDC | Unlimited | Unlimited | Unlimited | 0.25% |\n\nMerchant SaaS (portal): Starter $39 / Growth $79 / Scale $149 per month — separate product line.\n\nAccess control: every REST and MCP call is scoped by Postgres **row-level security (RLS)** to the owner wallet behind the `lsk_` / `rwk_` key.\n\nPayment: On-chain USDC transfer on Base, verified automatically. This covers **subscriptions only**.\n\n**Mint fee (separate, not USDC).** The mint fee % above is charged in the merchant's **own loyalty tokens** — a second `mint(address,uint256)` to the platform fee wallet on the same token contract. It is not USDC, ETH, or fiat, and it is independent of the per-call x402 / MPP prices. The token contract has no `mintWithFee`, so the fee is tracked off-chain as an obligation per prepared mint; 5+ obligations unpaid for over 60 minutes block further mints with HTTP 402. Settle with `POST /agent-api/mint/confirm` (REST) or `confirm_mint_fee` (MCP)."},{"id":"llms-full#26","source":"llms-full","title":"Smart Contracts","text":"New programs default to **B20** (Base native factory `0xB20f…`). Legacy Loyal Spark ERC-20 factory remains for `token_standard: \"erc20\"`. Details: `docs/development/LOYALTY_PROGRAM_CONTRACTS.md`.\n\n| Role | Address | Chain |\n|------|---------|-------|\n| B20 Factory (default deploy) | 0xB20f000000000000000000000000000000000000 | Base |\n| LoyaltyTokenFactory (legacy) | 0x5F3DdBa12580CFdc6016258774cCc19C4250dA80 | Base |\n| LoyalSparkERC20 (legacy impl) | 0xe6BA426C9c51281B929a17444De02c65815E27C3 | Base |\n| LoyaltyTokenEscrow | 0xA569C95AfC1BCF381c48BcF336ED9D2c014bcdDF | Base |\n| Builder Code | bc_wdmnog7m (ERC-8021) | Base |"},{"id":"llms-full#27","source":"llms-full","title":"P2P Marketplace (Escrow)","text":"Atomic token swaps via smart contract:\n1. Creator approves escrow for offer tokens\n2. Creator calls createOffer() — tokens locked\n3. Accepter approves escrow for request tokens\n4. Accepter calls fillOffer() — atomic swap\n5. Alternative: cancelOffer() returns tokens\n\nProtocol fee: 0.5% on completed swaps."},{"id":"llms-full#28","source":"llms-full","title":"Skills (Step-by-Step Guides)","text":"16 structured Markdown guides at `/.well-known/skills/`:\n- 00: Getting Started (register, API key, first request)\n- 01: Create Loyalty Program (B20 default, or legacy ERC-20)\n- 02: Mint Tokens\n- 03: Transfer Tokens\n- 04: Manage Rewards\n- 05: Balance and Tiers\n- 06: Marketplace Trading\n- 07: Analytics & CRM\n- 08: Referrals\n- 09: Vouchers\n- 10: Server Wallets (CDP MPC)\n- 11: Earn Points (cashback from purchases)\n- 12: Gift Certificates (LOYAL-XXXXXX welcome / gift codes, batch up to 100)\n- 13: Endpoint Workflows\n- 14: B20 Native Spec (Beryl)\n- 15: Payment Scenarios (x402 exact, MPP, subscriptions)"},{"id":"llms-full#29","source":"llms-full","title":"Tags","text":"loyalty, rewards, defi, base, erc20, ai-agents, mcp, rest-api, mpp, x402, cdp, mpc-wallet, p2p-marketplace, escrow, onchain"},{"id":"llms-full#30","source":"llms-full","title":"Contact","text":"- Website: https://loyalspark.online\n- Docs: https://loyalspark.online/api-docs\n- Email: admin@loyalspark.online\n- Twitter: https://x.com/Loyal_Spark"},{"id":"skill:00-getting-started#31","source":"skill:00-getting-started","title":"Skill 00 — Goal","text":"Register an AI agent, obtain an API key, and make your first authenticated request."},{"id":"skill:00-getting-started#32","source":"skill:00-getting-started","title":"Skill 00 — When to Use","text":"- You are an AI agent that needs to interact with onchain loyalty programs\n- You want to mint tokens, manage rewards, or trade on a marketplace\n- You need a server wallet for autonomous onchain transactions"},{"id":"skill:00-getting-started#33","source":"skill:00-getting-started","title":"Skill 00 — Step 1: Register Agent","text":"Pick **one** path:\n\n- **Merchant dashboard:** open [loyalspark.online/merchant](https://loyalspark.online/merchant) → **Sign In** until **Profile** appears → **AI Agents** → **Register Agent**. Fill in **Name**, **Description**, and **Scopes** (`read`, `mint`, `manage_rewards`, `trade`, `create_program`).\n\n- **Fully autonomous (no dashboard):** free `lsk_` via SIWE (`siwe-nonce` → sign EIP-4361 → `agent-register-siwe`). Details: **[AUTONOMOUS_AGENT_REGISTRATION.md](https://github.com/aspekt19/unboxed-loyalty-spark/blob/a2a-agents/docs/agents/AUTONOMOUS_AGENT_REGISTRATION.md)**. Optional developer helper (not part of the web app): `scripts/agent-register-siwe/` in the repo README."},{"id":"skill:00-getting-started#34","source":"skill:00-getting-started","title":"Skill 00 — Step 2: Get API Key","text":"Copy the generated API key (format: `lsk_...`). Store it securely — it cannot be retrieved again."},{"id":"skill:00-getting-started#35","source":"skill:00-getting-started","title":"Skill 00 — Step 3: Authenticate","text":"Include the API key in every request:\n\n**REST API:**\n```bash\ncurl -X GET \\\n  \"https://api.loyalspark.online/agent-api/me\" \\\n  -H \"x-api-key: lsk_your_key_here\"\n```\n\n**MCP Server:**\n```json\n{\n  \"mcpServers\": {\n    \"loyal-spark\": {\n      \"url\": \"https://api.loyalspark.online/loyalty-mcp\",\n      \"transport\": \"streamable-http\",\n      \"headers\": {\n        \"x-api-key\": \"lsk_your_key_here\"\n      }\n    }\n  }\n}\n```"},{"id":"skill:00-getting-started#36","source":"skill:00-getting-started","title":"Skill 00 — Step 4: Verify Connection","text":"Call `GET /me` (REST) or `get_my_profile` (MCP) to confirm authentication:\n\n```bash\ncurl -H \"x-api-key: lsk_...\" \\\n  \"https://api.loyalspark.online/agent-api/me\"\n```\n\n**Expected response:**\n```json\n{\n  \"agent\": {\n    \"id\": \"uuid\",\n    \"name\": \"My Agent\",\n    \"scopes\": [\"read\", \"mint\"],\n    \"owner_address\": \"0x...\"\n  }\n}\n```"},{"id":"skill:00-getting-started#37","source":"skill:00-getting-started","title":"Skill 00 — Step 4.5: Learn the Workflow Before Calling Write Endpoints","text":"Before using lifecycle, rewards, mint, vouchers, or marketplace endpoints, read the workflow guide:\n\n- [Endpoint Workflows](./13-endpoint-workflows.md)\n\nImportant orchestration rules:\n\n- `POST /programs` or `create_loyalty_program` starts a deploy flow; it does **not** finish it\n- new B20 programs become usable only after deploy + register\n- legacy ERC-20 programs need deploy + register + activate + status update\n- rewards usually come after the program exists\n- minting comes only after the program is active\n- voucher redemption comes only after confirmed onchain token transfer"},{"id":"skill:00-getting-started#38","source":"skill:00-getting-started","title":"Skill 00 — Step 5 (Optional): Pay-per-call MCP via x402 (Bazaar-compatible)","text":"If the agent should **pay USDC per MCP call** instead of using subscription-only access to `loyalty-mcp` or `recipient-loyalty-mcp`:\n\n- **Merchant tools:** **`POST`** `…/x402-gateway/mcp-tools/<tool_name>` — header **`x-api-key: lsk_...`** on the paid retry. Schemas: **`mcp-bazaar-tools.ts`**.\n- **Recipient / holder tools:** **`POST`** `…/x402-gateway/recipient-mcp-tools/<tool_name>` — **`x-api-key: rwk_...`**. Schemas: **`recipient-mcp-bazaar-tools.ts`**.\n- JSON-RPC **`tools/call`** with same **`name`** / **`arguments`** as direct MCP.\n- Use an x402 client (**`@x402/fetch`**, **`@x402/evm`**) and a wallet with **USDC on Base** to satisfy **HTTP 402**. The gateway adds **Bazaar**-oriented fields on **402** via **`x402-bazaar-accept.ts`** (MCP routes use `outputSchema.input.type: \"mcp\"` for both URL families)."},{"id":"skill:00-getting-started#39","source":"skill:00-getting-started","title":"Skill 00 — Step 6: Create Server Wallet (Optional)","text":"For autonomous onchain transactions, create a Coinbase MPC wallet:\n\n```bash\ncurl -X POST \\\n  \"https://api.loyalspark.online/agent-wallet\" \\\n  -H \"x-api-key: lsk_...\" \\\n  -H \"Content-Type: application/json\" \\\n  -d '{\"action\": \"create_wallet\"}'\n```"},{"id":"skill:00-getting-started#40","source":"skill:00-getting-started","title":"Skill 00 — Success Criteria","text":"- ✅ API key obtained and stored securely\n- ✅ `GET /me` returns agent profile\n- ✅ Scopes match intended operations"},{"id":"skill:00-getting-started#41","source":"skill:00-getting-started","title":"Skill 00 — Next Skills","text":"- [Create Loyalty Program](./01-create-loyalty-program.md)\n- [Mint Tokens](./02-mint-tokens.md)"},{"id":"skill:01-create-loyalty-program#42","source":"skill:01-create-loyalty-program","title":"Skill 01 — Goal","text":"Deploy a new **B20** loyalty token on Base (default) and register an **active** program. Legacy **ERC-20** factory remains available via `token_standard: \"erc20\"`."},{"id":"skill:01-create-loyalty-program#43","source":"skill:01-create-loyalty-program","title":"Skill 01 — When to Use","text":"- Launch a new loyalty/rewards program for a business\n- Autonomous agents: B20 grants `MINT_ROLE` to merchant + CDP wallet in one deploy tx"},{"id":"skill:01-create-loyalty-program#44","source":"skill:01-create-loyalty-program","title":"Skill 01 — B20 flow (default — deploy, then register)","text":"This skill covers only the **program creation** portion. A usable loyalty rollout usually continues with:\n\n1. create the program\n2. broadcast the one B20 factory transaction\n3. register the emitted token address\n4. create at least one reward\n5. then mint / earn points\n\nFor the full business sequence, see [13-endpoint-workflows.md](./13-endpoint-workflows.md) and the [B20 native specification](./14-b20-native-spec.md)."},{"id":"skill:01-create-loyalty-program#45","source":"skill:01-create-loyalty-program","title":"Skill 01 — Step 1: Get B20 deploy calldata","text":"```bash\ncurl -X POST \\\n  \"https://api.loyalspark.online/agent-api/programs\" \\\n  -H \"x-api-key: lsk_...\" \\\n  -H \"Content-Type: application/json\" \\\n  -d '{\n    \"name\": \"Coffee Rewards\",\n    \"symbol\": \"COFFEE\",\n    \"expiration_days\": 365\n  }'\n```\n\nOptional: `\"token_standard\": \"b20\"` (default), `\"agent_wallet_address\": \"0x...\"`, `\"extra_minters\": [\"0x...\"]`.\n\n**Response (B20):**\n```json\n{\n  \"message\": \"Execute the B20 factory transaction (single tx)...\",\n  \"program_details\": { \"token_standard\": \"b20\", \"name\": \"Coffee Rewards\", \"symbol\": \"COFFEE\" },\n  \"contract_call\": {\n    \"to\": \"0xB20f000000000000000000000000000000000000\",\n    \"function\": \"createB20(uint8,bytes32,bytes,bytes[])\",\n    \"calldata\": \"0x...\",\n    \"builder_code\": \"bc_wdmnog7m\",\n    \"mint_role_grantees\": [\"0xMerchant...\", \"0xCdpWallet...\"]\n  }\n}\n```\n\n**MCP equivalent:** `create_loyalty_program`"},{"id":"skill:01-create-loyalty-program#46","source":"skill:01-create-loyalty-program","title":"Skill 01 — Step 2: Execute deploy + register","text":"1. Broadcast `contract_call.calldata` to `contract_call.to` (one transaction).\n2. Extract `token_address` from **B20Created** event on the factory (`topic[1]`) or `GET /tx-receipt?tx_hash=0x...`.\n3. Register:\n\n```bash\ncurl -X POST \\\n  \"https://api.loyalspark.online/agent-api/register-program\" \\\n  -H \"x-api-key: lsk_...\" \\\n  -H \"Content-Type: application/json\" \\\n  -d '{\n    \"name\": \"Coffee Rewards\",\n    \"symbol\": \"COFFEE\",\n    \"token_address\": \"0xB200...\",\n    \"token_standard\": \"b20\",\n    \"expiration_days\": 365,\n    \"cashback_rate\": 5,\n    \"points_per_dollar\": 1\n  }'\n```\n\nProgram is saved as **`status: active`** — mint immediately. **No** `activate-program` step."},{"id":"skill:01-create-loyalty-program#47","source":"skill:01-create-loyalty-program","title":"Skill 01 — Step 3: Mint","text":"```bash\ncurl -X POST \\\n  \"https://api.loyalspark.online/agent-api/mint\" \\\n  -H \"x-api-key: lsk_...\" \\\n  -H \"Content-Type: application/json\" \\\n  -d '{ \"token_address\": \"0xB200...\", \"to\": \"0xCustomer...\", \"amount\": 100 }'\n```"},{"id":"skill:01-create-loyalty-program#48","source":"skill:01-create-loyalty-program","title":"Skill 01 — Legacy ERC-20 flow (`token_standard: \"erc20\"`)","text":"Add `\"token_standard\": \"erc20\"` to POST `/programs`. Factory: `0x5F3DdBa12580CFdc6016258774cCc19C4250dA80`, event **LoyaltyTokenCreated**.\n\nThen: `register-program` → `activate-program` (unpauseUtility + enableMinting, 2 txs) → `program-status` → `active`.\n\n**MCP:** `activate_loyalty_program` returns no-op for B20; legacy calldata for `erc20`."},{"id":"skill:01-create-loyalty-program#49","source":"skill:01-create-loyalty-program","title":"Skill 01 — Full flow summary (B20)","text":"```\nPOST /programs           → B20 factory calldata (1 tx)\n   ↓ execute on-chain\nPOST /register-program   → DB status: active, token_standard: b20\nPOST /mint               → distribute tokens\n```"},{"id":"skill:01-create-loyalty-program#50","source":"skill:01-create-loyalty-program","title":"Skill 01 — Success criteria","text":"- Program `status: \"active\"`, `token_standard: \"b20\"`\n- Token address starts with `0xB200…` (B20) or legacy proxy (erc20)\n- Appears in `GET /programs`\n- x402 / MCP mint and transfer work without activation"},{"id":"skill:01-create-loyalty-program#51","source":"skill:01-create-loyalty-program","title":"Skill 01 — Notes","text":"- B20 is a Base-native precompile-based ERC-20 superset. Its compatible balance, transfer, allowance, and mint interfaces keep the existing escrow and voucher flows usable.\n- B20 Asset roles, policies, granular pause, memo variants, and permit limitations are documented in [14-b20-native-spec.md](./14-b20-native-spec.md).\n- Builder Code `bc_wdmnog7m` is appended to deploy calldata\n- Existing ERC-20 programs keep working; only **new** deploys default to B20"},{"id":"skill:01-create-loyalty-program#52","source":"skill:01-create-loyalty-program","title":"Skill 01 — Next skills","text":"- [Mint Tokens](./02-mint-tokens.md)\n- [Manage Rewards](./04-manage-rewards.md)\n- [B20 Native Spec](./14-b20-native-spec.md)"},{"id":"skill:02-mint-tokens#53","source":"skill:02-mint-tokens","title":"Skill 02 — Goal","text":"Mint loyalty tokens to a customer wallet as a reward for purchases, engagement, or referrals."},{"id":"skill:02-mint-tokens#54","source":"skill:02-mint-tokens","title":"Skill 02 — When to Use","text":"- A customer made a purchase and should receive loyalty tokens\n- You want to reward a user for completing an action\n- An automation rule triggers a token distribution"},{"id":"skill:02-mint-tokens#55","source":"skill:02-mint-tokens","title":"Skill 02 — Step 1: Get Program Token Address","text":"List your programs to find the `token_address`:\n\n```bash\ncurl -H \"x-api-key: lsk_...\" \\\n  \"https://api.loyalspark.online/agent-api/programs\"\n```\n\nOnly mint into a program you own and that is already usable:\n\n- B20: registered and active\n- legacy ERC-20: activated and `program-status` updated to `active`"},{"id":"skill:02-mint-tokens#56","source":"skill:02-mint-tokens","title":"Skill 02 — Step 2: Mint Tokens via REST API","text":"```bash\ncurl -X POST \\\n  \"https://api.loyalspark.online/agent-api/mint\" \\\n  -H \"x-api-key: lsk_...\" \\\n  -H \"Content-Type: application/json\" \\\n  -d '{\n    \"token_address\": \"0xYourTokenAddress\",\n    \"recipient_address\": \"0xCustomerWallet\",\n    \"amount\": 100\n  }'\n```"},{"id":"skill:02-mint-tokens#57","source":"skill:02-mint-tokens","title":"Skill 02 — Step 3: Execute Onchain Transactions (fee-first)","text":"The API returns a **fee-first `calls[]` bundle** for the ERC-20-compatible `mint(address,uint256)` interface on the program token:\n\n1. **`calls[0]` — `purpose: \"protocol_fee\"`** — mint `fee_amount` (plan %) to `fee_wallet`. **Send this FIRST.**\n2. **`calls[1]` — `purpose: \"recipient_mint\"`** — mint full `amount` to the customer.\n\nFor a B20 Asset, this calls the Base-native token precompile and still requires the appropriate MINT role/policy. Submit the calls in order, or atomically in one batch via **EIP-5792 `wallet_sendCalls`** if your wallet supports it. B20 transactions benefit from Base's fast confirmations and low fees, but always wait for a receipt before confirming the obligation.\nLegacy fields `fee_calldata` / `recipient_calldata` are still returned for backwards compatibility, but `calls[]` is the source of truth for ordering.\n\nThis is **accountability**, not an on-chain atomic `mintWithFee`: the token contract does not enforce the fee. Instead every prepared mint writes a pending obligation (`fee_obligation_id`) that you must clear."},{"id":"skill:02-mint-tokens#58","source":"skill:02-mint-tokens","title":"Skill 02 — Step 4: Confirm the protocol fee","text":"```bash\ncurl -X POST \"https://api.loyalspark.online/agent-api/mint/confirm\" \\\n  -H \"x-api-key: lsk_...\" -H \"Content-Type: application/json\" \\\n  -d '{\"obligation_id\":\"<fee_obligation_id>\",\"fee_tx_hash\":\"0x...\",\"recipient_tx_hash\":\"0x...\"}'\n```\nThe server verifies the fee mint on Base (Transfer from the zero address to the platform wallet) and settles the obligation.\n**5 or more unpaid obligations older than 60 minutes block further mints with HTTP 402.**\n\n**Response (shape):**\n```json\n{\n  \"mint\": { \"id\": \"uuid\", \"amount\": 100, \"recipient_address\": \"0x...\", \"token_address\": \"0x...\" },\n  \"fee_percent\": 1.25,\n  \"fee_amount\": 1.25,\n  \"fee_wallet\": \"0x5cc0Aa9ed773F413f81f78a62F2e94109CE26205\",\n  \"fee_obligation_id\": \"uuid\",\n  \"calls\": [\n    { \"to\": \"0xToken\", \"data\": \"0x40c10f19...\", \"value\": \"0x0\", \"purpose\": \"protocol_fee\" },\n    { \"to\": \"0xToken\", \"data\": \"0x40c10f19...\", \"value\": \"0x0\", \"purpose\": \"recipient_mint\" }\n  ],\n  \"contract\": { \"function\": \"mint(address,uint256)\", \"chain\": \"Base (8453)\", \"builder_code\": \"bc_wdmnog7m\" }\n}\n```\n\n**MCP equivalent:** `mint_loyalty_tokens` + `confirm_mint_fee` (same fee-first model)."},{"id":"skill:02-mint-tokens#59","source":"skill:02-mint-tokens","title":"Skill 02 — Step 5: Verify Balance","text":"Check the customer's updated balance:\n\n```bash\ncurl -H \"x-api-key: lsk_...\" \\\n  \"https://api.loyalspark.online/agent-api/balance?token_address=0x...&customer_address=0x...\"\n```"},{"id":"skill:02-mint-tokens#60","source":"skill:02-mint-tokens","title":"Skill 02 — Transaction Fees","text":"The fee is **denominated in the loyalty tokens you are minting** — a separate `mint()` to the platform wallet on your own token contract. It is **not** USDC, ETH, or fiat, and it is separate from x402/MPP per-call pricing.\n\n| Plan | Mint commission (% of amount, as separate mint to platform) |\n|------|----------------------------------------------------------------|\n| Free | 1.25% |\n| Pro | 0.5% |\n| Enterprise | 0.25% |"},{"id":"skill:02-mint-tokens#61","source":"skill:02-mint-tokens","title":"Skill 02 — Success Criteria","text":"- ✅ Mint record created in database\n- ✅ Fee-first `calls[]` returned with builder code suffix\n- ✅ Customer balance updated after onchain execution\n- ✅ Fee obligation settled via `/agent-api/mint/confirm` (or MCP `confirm_mint_fee`)"},{"id":"skill:02-mint-tokens#62","source":"skill:02-mint-tokens","title":"Skill 02 — Next Skills","text":"- [Transfer Tokens](./03-transfer-tokens.md)\n- [Check Balance & Tiers](./05-balance-and-tiers.md)"},{"id":"skill:03-transfer-tokens#63","source":"skill:03-transfer-tokens","title":"Skill 03 — Goal","text":"Transfer loyalty tokens between wallets — for P2P transfers, rewards distribution, or inter-agent operations."},{"id":"skill:03-transfer-tokens#64","source":"skill:03-transfer-tokens","title":"Skill 03 — When to Use","text":"- Transfer tokens from one wallet to another\n- Distribute tokens from a treasury wallet\n- Agent-to-agent token transfer"},{"id":"skill:03-transfer-tokens#65","source":"skill:03-transfer-tokens","title":"Skill 03 — Step 1: Verify Program Ownership","text":"Ensure the token belongs to your program:\n\n```bash\ncurl -H \"x-api-key: lsk_...\" \\\n  \"https://api.loyalspark.online/agent-api/programs\"\n```"},{"id":"skill:03-transfer-tokens#66","source":"skill:03-transfer-tokens","title":"Skill 03 — Step 2: Transfer via REST API","text":"```bash\ncurl -X POST \\\n  \"https://api.loyalspark.online/agent-api/transfer\" \\\n  -H \"x-api-key: lsk_...\" \\\n  -H \"Content-Type: application/json\" \\\n  -d '{\n    \"token_address\": \"0xYourTokenAddress\",\n    \"to_address\": \"0xRecipientWallet\",\n    \"amount\": 50\n  }'\n```"},{"id":"skill:03-transfer-tokens#67","source":"skill:03-transfer-tokens","title":"Skill 03 — Step 3: Execute Onchain Transaction","text":"The API returns calldata for `transfer(address,uint256)`:\n\n**Response:**\n```json\n{\n  \"contract_call\": {\n    \"to\": \"0xYourTokenAddress\",\n    \"function\": \"transfer(address,uint256)\",\n    \"args\": [\"0xRecipientWallet\", 50],\n    \"calldata\": \"0xa9059cbb...\",\n    \"chain\": \"Base (8453)\",\n    \"builder_code\": \"bc_wdmnog7m\"\n  }\n}\n```\n\n**MCP equivalent:** `transfer_loyalty_tokens`"},{"id":"skill:03-transfer-tokens#68","source":"skill:03-transfer-tokens","title":"Skill 03 — Recipient holders (`rwk_`) — same transfer, different auth","text":"Merchants use `lsk_` + `transfer_loyalty_tokens`. **Token holders** (customer / autonomous agent bound to one wallet) use **`rwk_`**:\n\n- **MCP:** `prepare_loyalty_token_transfer` on `recipient-loyalty-mcp` (B20-compatible `transfer(address,uint256)` + Builder Code; amount in human units, 18 decimals in encoding — same as merchant tool).\n- **REST:** `POST …/recipient-api/prepare-transfer` with JSON `{ \"token_address\", \"to\", \"amount\" }` and header `x-api-key: rwk_…`.\n\nThe loyalty program must exist and be **`active`** in Loyal Spark. The signing EOA must be the wallet bound to the `rwk_` key; recipients can send to **any** address when the B20 transfer policy allows it. For Base smart accounts, use normal `approve` calldata for escrow: B20 ERC-2612 permit uses version `\"1\"` and does not accept ERC-1271 contract signatures."},{"id":"skill:03-transfer-tokens#69","source":"skill:03-transfer-tokens","title":"Skill 03 — Important Notes","text":"- Transfer requires the sender to hold sufficient token balance\n- If a B20 transfer reverts, inspect `TRANSFER_SENDER` / `TRANSFER_RECEIVER` policy scopes and granular `TRANSFER` pause before assuming a balance problem\n- The calldata includes Base Builder Code for attribution\n- Program must be in `active` status"},{"id":"skill:03-transfer-tokens#70","source":"skill:03-transfer-tokens","title":"Skill 03 — Success Criteria","text":"- ✅ Calldata generated with correct recipient and amount\n- ✅ Transaction executed onchain successfully\n- ✅ Recipient balance updated"},{"id":"skill:03-transfer-tokens#71","source":"skill:03-transfer-tokens","title":"Skill 03 — Next Skills","text":"- [Mint Tokens](./02-mint-tokens.md)\n- [Marketplace Trading](./06-marketplace-trading.md)"},{"id":"skill:04-manage-rewards#72","source":"skill:04-manage-rewards","title":"Skill 04 — Goal","text":"Create and manage redeemable rewards that customers can claim by burning loyalty tokens."},{"id":"skill:04-manage-rewards#73","source":"skill:04-manage-rewards","title":"Skill 04 — When to Use","text":"- You want to offer discounts, products, or experiences in exchange for tokens\n- Setting up a reward catalog for a loyalty program\n- Managing active/inactive rewards"},{"id":"skill:04-manage-rewards#74","source":"skill:04-manage-rewards","title":"Skill 04 — Prerequisite","text":"Before creating rewards, make sure the loyalty program already exists and is usable:\n\n- B20: deploy -> register\n- legacy ERC-20: deploy -> register -> activate -> program-status active"},{"id":"skill:04-manage-rewards#75","source":"skill:04-manage-rewards","title":"Skill 04 — Step 1: List Existing Rewards","text":"```bash\ncurl -H \"x-api-key: lsk_...\" \\\n  \"https://api.loyalspark.online/agent-api/rewards?token_address=0xYourToken\"\n```\n\n**MCP equivalent:** `list_rewards` with `token_address` parameter"},{"id":"skill:04-manage-rewards#76","source":"skill:04-manage-rewards","title":"Skill 04 — Step 2: Create a New Reward","text":"```bash\ncurl -X POST \\\n  \"https://api.loyalspark.online/agent-api/rewards\" \\\n  -H \"x-api-key: lsk_...\" \\\n  -H \"Content-Type: application/json\" \\\n  -d '{\n    \"token_address\": \"0xYourTokenAddress\",\n    \"name\": \"Free Coffee\",\n    \"description\": \"Redeem for one free coffee at any location\",\n    \"cost\": 50\n  }'\n```\n\n**MCP equivalent:** `create_reward`"},{"id":"skill:04-manage-rewards#77","source":"skill:04-manage-rewards","title":"Skill 04 — Step 3: Verify Reward Created","text":"**Response:**\n```json\n{\n  \"reward\": {\n    \"id\": \"uuid\",\n    \"name\": \"Free Coffee\",\n    \"description\": \"Redeem for one free coffee at any location\",\n    \"cost\": 50,\n    \"is_active\": true,\n    \"created_at\": \"2026-03-23T...\"\n  }\n}\n```"},{"id":"skill:04-manage-rewards#78","source":"skill:04-manage-rewards","title":"Skill 04 — Reward Design Tips","text":"- Set `cost` proportional to reward value (e.g., 50 tokens = $5 value)\n- Use clear, descriptive names customers will understand\n- Create tiered rewards: small (10 tokens), medium (50), premium (200)\n- Deactivate rewards instead of deleting to preserve history"},{"id":"skill:04-manage-rewards#79","source":"skill:04-manage-rewards","title":"Skill 04 — Success Criteria","text":"- ✅ Reward created with `is_active: true`\n- ✅ Cost is reasonable relative to token earning rate\n- ✅ Reward appears in `GET /rewards` list"},{"id":"skill:04-manage-rewards#80","source":"skill:04-manage-rewards","title":"Skill 04 — Next Skills","text":"- [Voucher Management](./09-vouchers.md) — track redeemed rewards\n- [Check Balance & Tiers](./05-balance-and-tiers.md) — verify customers can afford rewards"},{"id":"skill:05-balance-and-tiers#81","source":"skill:05-balance-and-tiers","title":"Skill 05 — Goal","text":"Query a customer's token balance and tier status to personalize interactions."},{"id":"skill:05-balance-and-tiers#82","source":"skill:05-balance-and-tiers","title":"Skill 05 — When to Use","text":"- Check if a customer has enough tokens to redeem a reward\n- Determine a customer's loyalty tier for personalized offers\n- Monitor token distribution across your customer base"},{"id":"skill:05-balance-and-tiers#83","source":"skill:05-balance-and-tiers","title":"Skill 05 — Step 1: Check Individual Balance","text":"```bash\ncurl -H \"x-api-key: lsk_...\" \\\n  \"https://api.loyalspark.online/agent-api/balance?token_address=0x...&customer_address=0x...\"\n```\n\n**MCP equivalent:** `get_token_balance`\n\n**Response:**\n```json\n{\n  \"balance\": {\n    \"current\": 150,\n    \"total_earned\": 500,\n    \"tier\": {\n      \"tier_name\": \"Gold\",\n      \"tier_level\": 2,\n      \"badge_color\": \"#FFD700\",\n      \"cashback_multiplier\": 1.5\n    }\n  }\n}\n```"},{"id":"skill:05-balance-and-tiers#84","source":"skill:05-balance-and-tiers","title":"Skill 05 — Step 2: List All Customers","text":"```bash\ncurl -H \"x-api-key: lsk_...\" \\\n  \"https://api.loyalspark.online/agent-api/customers?token_address=0x...\"\n```"},{"id":"skill:05-balance-and-tiers#85","source":"skill:05-balance-and-tiers","title":"Skill 05 — Step 3: Use Tier Data for Decisions","text":"Based on tier information, adjust your agent's behavior:\n- **Bronze** (level 1): Standard rewards, basic offers\n- **Silver** (level 2): Bonus tokens on purchases, priority support\n- **Gold** (level 3): Exclusive rewards, higher cashback multiplier\n- **Platinum** (level 4): VIP access, maximum cashback"},{"id":"skill:05-balance-and-tiers#86","source":"skill:05-balance-and-tiers","title":"Skill 05 — Decision Logic Example","text":"```\nIF customer.balance >= reward.cost THEN\n  → Suggest redeeming the reward\nELSE\n  → Calculate tokens needed: reward.cost - customer.balance\n  → Suggest actions to earn more tokens\n\nIF customer.tier.cashback_multiplier > 1.0 THEN\n  → Apply bonus: mint_amount * cashback_multiplier\n```"},{"id":"skill:05-balance-and-tiers#87","source":"skill:05-balance-and-tiers","title":"Skill 05 — Success Criteria","text":"- ✅ Balance retrieved with current and total_earned values\n- ✅ Tier information includes level and multiplier\n- ✅ Agent can make decisions based on tier data"},{"id":"skill:05-balance-and-tiers#88","source":"skill:05-balance-and-tiers","title":"Skill 05 — Next Skills","text":"- [Mint Tokens](./02-mint-tokens.md) — reward customers\n- [Manage Rewards](./04-manage-rewards.md) — set up redeemable items"},{"id":"skill:06-marketplace-trading#89","source":"skill:06-marketplace-trading","title":"Skill 06 — When to Use","text":"- Exchange loyalty tokens between different programs\n- Create liquidity for your program's tokens\n- Accept or cancel existing marketplace offers"},{"id":"skill:06-marketplace-trading#90","source":"skill:06-marketplace-trading","title":"Skill 06 — How It Works","text":"The marketplace uses a smart contract escrow on Base for atomic swaps:\n1. Creator approves escrow contract → locks offer tokens\n2. Accepter approves escrow contract → calls `fillOffer()` \n3. Atomic swap executes — both transfers happen in one transaction, or neither does\n\n**Escrow Contract:** `0xA569C95AfC1BCF381c48BcF336ED9D2c014bcdDF`  \n**Protocol Fee:** 0.5% on completed swaps"},{"id":"skill:06-marketplace-trading#91","source":"skill:06-marketplace-trading","title":"Skill 06 — Step 1: List Active Offers","text":"```bash\ncurl -H \"x-api-key: lsk_...\" \\\n  \"https://api.loyalspark.online/agent-api/offers?token_address=0xYourToken\"\n```\n\nServer returns active offers only (status filter and limit are fixed server-side).\n\n**MCP equivalent:** `list_marketplace_offers`"},{"id":"skill:06-marketplace-trading#92","source":"skill:06-marketplace-trading","title":"Skill 06 — Step 2: Create an Offer","text":"```bash\ncurl -X POST \\\n  \"https://api.loyalspark.online/agent-api/offers\" \\\n  -H \"x-api-key: lsk_...\" \\\n  -H \"Content-Type: application/json\" \\\n  -d '{\n    \"offer_token_address\": \"0xYourToken\",\n    \"offer_amount\": 100,\n    \"request_token_address\": \"0xDesiredToken\",\n    \"request_amount\": 50\n  }'\n```"},{"id":"skill:06-marketplace-trading#93","source":"skill:06-marketplace-trading","title":"Skill 06 — Step 3: Accept an Offer (two-phase)","text":"**Phase 1 — reserve** (no `transaction_hash`): the offer becomes `accepted` (reserved for your wallet) and the response returns `approve` + `fillOffer` escrow calldata.\n\n```bash\ncurl -X POST \\\n  \"https://api.loyalspark.online/agent-api/accept-offer\" \\\n  -H \"x-api-key: lsk_...\" \\\n  -H \"Content-Type: application/json\" \\\n  -d '{\"offer_id\": \"uuid-of-the-offer\", \"onchain_offer_id\": 42}'\n```\n\n**Phase 2 — finalize**: after the escrow `fillOffer` transaction confirms, call again with `transaction_hash`. The API verifies the tx on Base and sets the offer to `completed`.\n\n```bash\ncurl -X POST \\\n  \"https://api.loyalspark.online/agent-api/accept-offer\" \\\n  -H \"x-api-key: lsk_...\" \\\n  -H \"Content-Type: application/json\" \\\n  -d '{\"offer_id\": \"uuid-of-the-offer\", \"transaction_hash\": \"0x...\"}'\n```"},{"id":"skill:06-marketplace-trading#94","source":"skill:06-marketplace-trading","title":"Skill 06 — Step 4: Cancel Your Offer","text":"```bash\ncurl -X POST \\\n  \"https://api.loyalspark.online/agent-api/cancel-offer\" \\\n  -H \"x-api-key: lsk_...\" \\\n  -H \"Content-Type: application/json\" \\\n  -d '{\"offer_id\": \"uuid-of-your-offer\"}'\n```"},{"id":"skill:06-marketplace-trading#95","source":"skill:06-marketplace-trading","title":"Skill 06 — Trading Strategy Tips","text":"- Monitor exchange rates between popular token pairs\n- Set competitive rates to attract counter-parties\n- Cancel stale offers to free locked tokens\n- Use `limit` parameter to paginate large result sets"},{"id":"skill:06-marketplace-trading#96","source":"skill:06-marketplace-trading","title":"Skill 06 — Success Criteria","text":"- ✅ Offers listed with correct status filtering\n- ✅ New offer created with escrow calldata returned\n- ✅ Offer accepted/cancelled with correct onchain calldata"},{"id":"skill:06-marketplace-trading#97","source":"skill:06-marketplace-trading","title":"Skill 06 — Next Skills","text":"- [Transfer Tokens](./03-transfer-tokens.md) — direct transfers without marketplace\n- [Analytics & CRM](./07-analytics-crm.md) — track trading activity"},{"id":"skill:07-analytics-crm#98","source":"skill:07-analytics-crm","title":"Skill 07 — Goal","text":"Access program analytics, customer data, and performance metrics to make data-driven decisions."},{"id":"skill:07-analytics-crm#99","source":"skill:07-analytics-crm","title":"Skill 07 — When to Use","text":"- Monitor program health and engagement metrics\n- Segment customers by activity and token holdings\n- Generate reports on token distribution and redemption"},{"id":"skill:07-analytics-crm#100","source":"skill:07-analytics-crm","title":"Skill 07 — Step 1: Get Program Analytics","text":"```bash\ncurl -H \"x-api-key: lsk_...\" \\\n  \"https://api.loyalspark.online/agent-api/analytics\"\n```\n\n**MCP equivalent:** `get_program_analytics`\n\n**Response:**\n```json\n{\n  \"analytics\": [\n    {\n      \"program_name\": \"Coffee Rewards\",\n      \"token_address\": \"0x...\",\n      \"token_symbol\": \"COFFEE\",\n      \"total_customers\": 150,\n      \"active_customers_7d\": 45,\n      \"active_customers_30d\": 89,\n      \"total_vouchers_issued\": 320,\n      \"vouchers_redeemed\": 210,\n      \"total_tokens_spent\": 15000,\n      \"avg_voucher_cost\": 47\n    }\n  ]\n}\n```"},{"id":"skill:07-analytics-crm#101","source":"skill:07-analytics-crm","title":"Skill 07 — Step 2: List Customers","text":"```bash\ncurl -H \"x-api-key: lsk_...\" \\\n  \"https://api.loyalspark.online/agent-api/customers?token_address=0x...\"\n```"},{"id":"skill:07-analytics-crm#102","source":"skill:07-analytics-crm","title":"Skill 07 — Step 3: Analyze Key Metrics","text":"**Engagement Rate:** `active_customers_30d / total_customers × 100`  \n**Redemption Rate:** `vouchers_redeemed / total_vouchers_issued × 100`  \n**Avg Token Spend:** `total_tokens_spent / vouchers_redeemed`"},{"id":"skill:07-analytics-crm#103","source":"skill:07-analytics-crm","title":"Skill 07 — Step 4: Act on Insights","text":"| Metric | Low | Action |\n|--------|-----|--------|\n| Engagement < 30% | Low activity | Mint bonus tokens to inactive users |\n| Redemption < 50% | Rewards too expensive | Lower reward costs or create cheaper options |\n| Active 7d declining | Losing momentum | Launch a campaign or referral program |"},{"id":"skill:07-analytics-crm#104","source":"skill:07-analytics-crm","title":"Skill 07 — Decision Logic","text":"```\nIF active_customers_30d < total_customers * 0.3 THEN\n  → Trigger re-engagement: mint bonus tokens to dormant wallets\n  \nIF vouchers_redeemed / total_vouchers_issued < 0.5 THEN\n  → Create lower-cost rewards to encourage redemption\n\nIF active_customers_7d > active_customers_30d * 0.7 THEN\n  → Program is healthy — consider expansion\n```"},{"id":"skill:07-analytics-crm#105","source":"skill:07-analytics-crm","title":"Skill 07 — Success Criteria","text":"- ✅ Analytics data retrieved for all programs\n- ✅ Key metrics calculated and actionable\n- ✅ Agent can recommend improvements based on data"},{"id":"skill:07-analytics-crm#106","source":"skill:07-analytics-crm","title":"Skill 07 — Next Skills","text":"- [Mint Tokens](./02-mint-tokens.md) — act on engagement insights\n- [Manage Rewards](./04-manage-rewards.md) — optimize reward catalog"},{"id":"skill:08-referrals#107","source":"skill:08-referrals","title":"Skill 08 — Goal","text":"Set up and manage referral programs where existing customers bring new ones, earning bonus tokens for both parties."},{"id":"skill:08-referrals#108","source":"skill:08-referrals","title":"Skill 08 — When to Use","text":"- You want organic customer growth through word-of-mouth\n- Reward existing customers for bringing friends\n- Track referral effectiveness and conversion rates"},{"id":"skill:08-referrals#109","source":"skill:08-referrals","title":"Skill 08 — How Referrals Work","text":"1. Merchant sets up referral program with bonus amounts\n2. Existing customer generates a referral code\n3. New customer uses the code when joining\n4. Both referrer and referee receive bonus tokens"},{"id":"skill:08-referrals#110","source":"skill:08-referrals","title":"Skill 08 — Step 1: Check Existing Referral Program","text":"Query referral programs for your token:\n\n```bash\ncurl -H \"x-api-key: lsk_...\" \\\n  \"https://api.loyalspark.online/agent-api/programs\"\n```"},{"id":"skill:08-referrals#111","source":"skill:08-referrals","title":"Skill 08 — Step 2: Configure Referral Bonuses","text":"Referral programs are configured per loyalty program with:\n- **referrer_bonus**: Tokens the referrer earns (e.g., 20)\n- **referee_bonus**: Tokens the new user earns (e.g., 10)\n- **max_referrals_per_user**: Cap to prevent abuse (e.g., 50)\n- **min_purchase_required**: Optional minimum to qualify"},{"id":"skill:08-referrals#112","source":"skill:08-referrals","title":"Skill 08 — Step 3: Generate Referral Code","text":"Referral codes are generated per customer per program using the database function `generate_referral_code`."},{"id":"skill:08-referrals#113","source":"skill:08-referrals","title":"Skill 08 — Step 4: Process Referral","text":"When a new customer uses a referral code, the system:\n1. Validates the code and checks limits\n2. Records the referral relationship\n3. Mints bonus tokens to both parties"},{"id":"skill:08-referrals#114","source":"skill:08-referrals","title":"Skill 08 — Step 5: Track Referral Performance","text":"Monitor referral metrics through analytics:\n- Total referrals generated\n- Conversion rate (codes used / codes generated)\n- Top referrers by count\n- Revenue attributed to referrals"},{"id":"skill:08-referrals#115","source":"skill:08-referrals","title":"Skill 08 — Best Practices","text":"- Set referee bonus ≥ 50% of referrer bonus to incentivize new users\n- Cap max referrals to prevent gaming (50-100 is typical)\n- Increase bonuses during launch phases for faster growth\n- Track which referrers drive the most valuable customers"},{"id":"skill:08-referrals#116","source":"skill:08-referrals","title":"Skill 08 — Success Criteria","text":"- ✅ Referral program configured with appropriate bonuses\n- ✅ Codes generated and shareable\n- ✅ Both parties receive bonuses on successful referral\n- ✅ Abuse prevention via max referral caps"},{"id":"skill:08-referrals#117","source":"skill:08-referrals","title":"Skill 08 — Next Skills","text":"- [Analytics & CRM](./07-analytics-crm.md) — track referral ROI\n- [Mint Tokens](./02-mint-tokens.md) — distribute referral bonuses"},{"id":"skill:09-vouchers#118","source":"skill:09-vouchers","title":"Skill 09 — Goal","text":"Full lifecycle management of vouchers — from redeeming rewards (burning tokens) to marking vouchers as used."},{"id":"skill:09-vouchers#119","source":"skill:09-vouchers","title":"Skill 09 — Required Scopes","text":"- `read` — to redeem rewards and create vouchers\n- `manage_rewards` — to mark vouchers as used"},{"id":"skill:09-vouchers#120","source":"skill:09-vouchers","title":"Skill 09 — When to Use","text":"- Customer agent wants to redeem a reward (exchange tokens for a voucher)\n- Merchant agent wants to verify and mark a voucher as used\n- Query voucher status and history"},{"id":"skill:09-vouchers#121","source":"skill:09-vouchers","title":"Skill 09 — How Vouchers Work (Agent Flow)","text":"1. Customer's agent transfers tokens to the merchant's wallet (on-chain ERC-20 transfer)\n2. Agent calls `POST /redeem-reward` with the transaction hash → system verifies the transfer on-chain and creates a voucher\n3. Customer presents voucher code to merchant\n4. Merchant's agent calls `POST /vouchers/use` to mark it as used\n\nThis is a good example of a workflow where one API call is **not** enough. Treat the onchain transfer and the voucher endpoint as separate required steps."},{"id":"skill:09-vouchers#122","source":"skill:09-vouchers","title":"Skill 09 — Voucher Lifecycle","text":"```\n[Agent transfers tokens on-chain] → [POST /redeem-reward with tx_hash]\n                                        ↓\n                              [Voucher created: status=active]\n                                        ↓\n                              [Customer presents voucher code]\n                                        ↓\n                              [Merchant: POST /vouchers/use]\n                                        ↓\n                              [Voucher status=used, used_at set]\n```"},{"id":"skill:09-vouchers#123","source":"skill:09-vouchers","title":"Skill 09 — Step 1: List Available Rewards","text":"```bash\ncurl -H \"x-api-key: lsk_...\" \\\n  \"https://api.loyalspark.online/agent-api/rewards?token_address=0x...\"\n```"},{"id":"skill:09-vouchers#124","source":"skill:09-vouchers","title":"Skill 09 — Step 2: Transfer Tokens (On-Chain)","text":"The customer agent must execute an ERC-20 `transfer(merchant_address, cost)` on-chain.\nUse the `/transfer` endpoint to get the calldata:\n\n```bash\ncurl -X POST \\\n  \"https://api.loyalspark.online/agent-api/transfer\" \\\n  -H \"x-api-key: lsk_...\" \\\n  -H \"Content-Type: application/json\" \\\n  -d '{\n    \"token_address\": \"0xTokenAddress\",\n    \"to_address\": \"0xMerchantAddress\",\n    \"amount\": 50\n  }'\n```"},{"id":"skill:09-vouchers#125","source":"skill:09-vouchers","title":"Skill 09 — Step 3: Redeem Reward (Create Voucher)","text":"After the transfer is confirmed on-chain, create a voucher:\n\n```bash\ncurl -X POST \\\n  \"https://api.loyalspark.online/agent-api/redeem-reward\" \\\n  -H \"x-api-key: lsk_...\" \\\n  -H \"Content-Type: application/json\" \\\n  -d '{\n    \"reward_id\": \"uuid-of-reward\",\n    \"customer_address\": \"0xCustomerAddress\",\n    \"transaction_hash\": \"0xTransferTxHash\"\n  }'\n```\n\nResponse:\n```json\n{\n  \"voucher\": {\n    \"id\": \"uuid\",\n    \"code\": \"LOYAL-AB12-CD34-EF56-GH78\",\n    \"reward_name\": \"Free Coffee\",\n    \"cost\": 50,\n    \"status\": \"active\",\n    \"activated_at\": \"2026-04-02T...\",\n    \"transaction_hash\": \"0x...\"\n  }\n}\n```"},{"id":"skill:09-vouchers#126","source":"skill:09-vouchers","title":"Skill 09 — Step 4: Use Voucher (Merchant)","text":"When the customer presents the voucher, the merchant agent marks it as used:\n\n```bash\ncurl -X POST \\\n  \"https://api.loyalspark.online/agent-api/vouchers/use\" \\\n  -H \"x-api-key: lsk_...\" \\\n  -H \"Content-Type: application/json\" \\\n  -d '{\n    \"voucher_code\": \"LOYAL-AB12-CD34-EF56-GH78\"\n  }'\n```\n\nOr by voucher ID:\n```json\n{ \"voucher_id\": \"uuid-of-voucher\" }\n```"},{"id":"skill:09-vouchers#127","source":"skill:09-vouchers","title":"Skill 09 — Step 5: Check Voucher Status (Public — No API Key)","text":"Anyone (customer, agent, or third party) can check a voucher's status:\n\n```bash\ncurl \"https://api.loyalspark.online/agent-api/vouchers/status?code=LOYAL-AB12-CD34-EF56-GH78\"\n```\n\nResponse:\n```json\n{\n  \"voucher\": {\n    \"id\": \"uuid\",\n    \"code\": \"LOYAL-AB12-CD34-EF56-GH78\",\n    \"reward_name\": \"Free Coffee\",\n    \"status\": \"active\",\n    \"cost\": 50,\n    \"token_symbol\": \"COFFEE\",\n    \"merchant_address\": \"0x...\",\n    \"activated_at\": \"2026-04-02T...\",\n    \"used_at\": null\n  }\n}\n```"},{"id":"skill:09-vouchers#128","source":"skill:09-vouchers","title":"Skill 09 — Step 6: View Vouchers (Merchant)","text":"Query vouchers for your program:\n\n```bash\ncurl -H \"x-api-key: lsk_...\" \\\n  \"https://api.loyalspark.online/agent-api/vouchers?token_address=0x...&status=active\"\n```"},{"id":"skill:09-vouchers#129","source":"skill:09-vouchers","title":"Skill 09 — Step 6: Track Redemption Metrics","text":"From analytics, monitor:\n- **total_vouchers_issued**: How many rewards were claimed\n- **vouchers_redeemed**: How many were actually used\n- **avg_voucher_cost**: Average token cost per redemption"},{"id":"skill:09-vouchers#130","source":"skill:09-vouchers","title":"Skill 09 — MCP Server Tools","text":"The same functionality is available via MCP:\n- `redeem_reward` — Create a voucher from a verified token transfer\n- `use_voucher` — Mark a voucher as used\n- `check_voucher_status` — Check voucher status (public, no key needed)\n- `list_vouchers` — Query vouchers by status"},{"id":"skill:09-vouchers#131","source":"skill:09-vouchers","title":"Skill 09 — Best Practices","text":"- Always wait for on-chain confirmation before calling `/redeem-reward`\n- If the transaction isn't confirmed yet, the API returns `retryable: true` — retry after 3 seconds\n- Vouchers with `status: \"active\"` are valid for redemption\n- High voucher issuance but low redemption = rewards may be impractical"},{"id":"skill:09-vouchers#132","source":"skill:09-vouchers","title":"Skill 09 — Success Criteria","text":"- ✅ Reward redeemed via token transfer + voucher creation\n- ✅ Voucher marked as used by merchant\n- ✅ Redemption rate tracked via analytics"},{"id":"skill:09-vouchers#133","source":"skill:09-vouchers","title":"Skill 09 — Next Skills","text":"- [Manage Rewards](./04-manage-rewards.md) — adjust reward catalog\n- [Analytics & CRM](./07-analytics-crm.md) — deep dive into metrics"},{"id":"skill:10-server-wallets#134","source":"skill:10-server-wallets","title":"Skill 10 — Goal","text":"Create and manage autonomous server wallets for AI agents to sign onchain transactions without exposing private keys."},{"id":"skill:10-server-wallets#135","source":"skill:10-server-wallets","title":"Skill 10 — Required Scope","text":"None (available to all authenticated agents)"},{"id":"skill:10-server-wallets#136","source":"skill:10-server-wallets","title":"Skill 10 — When to Use","text":"- Your agent needs to execute onchain transactions autonomously\n- You want MPC-secured key management by Coinbase\n- You need a dedicated wallet for each agent"},{"id":"skill:10-server-wallets#137","source":"skill:10-server-wallets","title":"Skill 10 — How It Works","text":"Loyal Spark integrates Coinbase CDP (Coinbase Developer Platform) MPC wallets:\n- **MPC (Multi-Party Computation)**: Private key is split across multiple parties — no single point of failure\n- **Server-side signing**: Transactions are signed without exposing keys\n- **Base native**: Wallets operate on Base L2 (Chain ID: 8453)"},{"id":"skill:10-server-wallets#138","source":"skill:10-server-wallets","title":"Skill 10 — Step 1: Create a Server Wallet","text":"```bash\ncurl -X POST \\\n  \"https://api.loyalspark.online/agent-wallet\" \\\n  -H \"x-api-key: lsk_...\" \\\n  -H \"Content-Type: application/json\" \\\n  -d '{\"action\": \"create_wallet\"}'\n```\n\n**Response:**\n```json\n{\n  \"wallet\": {\n    \"id\": \"uuid\",\n    \"wallet_address\": \"0xNewWalletAddress\",\n    \"chain_id\": 8453,\n    \"wallet_type\": \"cdp_mpc\",\n    \"is_active\": true\n  }\n}\n```"},{"id":"skill:10-server-wallets#139","source":"skill:10-server-wallets","title":"Skill 10 — Step 2: Fund the Wallet","text":"Send ETH (for gas) to the wallet address on Base. The wallet needs a small ETH balance to pay transaction fees."},{"id":"skill:10-server-wallets#140","source":"skill:10-server-wallets","title":"Skill 10 — Step 3: Use Wallet for Operations","text":"Once funded, the agent can:\n- Execute mint calldata returned by `/mint` endpoint\n- Execute transfer calldata from `/transfer` endpoint\n- Accept marketplace offers via `/accept-offer`\n- All transactions signed server-side via MPC\n\n**Protocol fee on mints.** When you execute the `/mint` or `/earn` calldata yourself, you must send **both** calls in order — the `protocol_fee` mint first, then `recipient_mint` — and settle the obligation with `POST /agent-api/mint/confirm` (see [02-mint-tokens.md](./02-mint-tokens.md)). The fee is charged in your own loyalty tokens, not USDC. If you instead use `POST /agent-wallet` with `action: \"server_mint\"`, Loyal Spark sends the fee transaction itself and aborts the recipient mint if the fee fails, so no confirmation step is needed."},{"id":"skill:10-server-wallets#141","source":"skill:10-server-wallets","title":"Skill 10 — Step 4: Check Wallet Status","text":"Your wallet info is included in the `GET /me` response:\n\n```bash\ncurl -H \"x-api-key: lsk_...\" \\\n  \"https://api.loyalspark.online/agent-api/me\"\n```"},{"id":"skill:10-server-wallets#142","source":"skill:10-server-wallets","title":"Skill 10 — Security Model","text":"| Feature | Detail |\n|---------|--------|\n| Key Storage | Split across MPC parties by Coinbase |\n| Key Exposure | Never — keys are never assembled in one place |\n| Transaction Signing | Server-side, no client involvement |\n| Chain | Base L2 (8453) |\n| Provider | Coinbase CDP |"},{"id":"skill:10-server-wallets#143","source":"skill:10-server-wallets","title":"Skill 10 — Best Practices","text":"- Create one wallet per agent for clear accounting\n- Keep minimal ETH balance for gas — replenish as needed\n- Monitor wallet activity through agent activity logs\n- Wallet address is permanent — use it as the agent's onchain identity"},{"id":"skill:10-server-wallets#144","source":"skill:10-server-wallets","title":"Skill 10 — Success Criteria","text":"- ✅ Wallet created with valid Base address\n- ✅ Wallet funded with ETH for gas\n- ✅ Agent can execute calldata through the wallet\n- ✅ Wallet appears in `GET /me` response"},{"id":"skill:10-server-wallets#145","source":"skill:10-server-wallets","title":"Skill 10 — Next Skills","text":"- [Getting Started](./00-getting-started.md) — full setup guide\n- [Mint Tokens](./02-mint-tokens.md) — first operation with your wallet"},{"id":"skill:11-earn-points#146","source":"skill:11-earn-points","title":"Skill 11 — Goal","text":"Automatically calculate and mint loyalty tokens based on a customer's purchase amount, using the program's cashback rate."},{"id":"skill:11-earn-points#147","source":"skill:11-earn-points","title":"Skill 11 — When to Use","text":"- A customer made a purchase and should receive loyalty tokens proportional to the amount spent\n- You want to automate point-of-sale token distribution\n- A cashier scans a customer's QR and enters the purchase amount"},{"id":"skill:11-earn-points#148","source":"skill:11-earn-points","title":"Skill 11 — How It Works","text":"Instead of manually calculating how many tokens to mint, the `/earn` endpoint does it for you:\n\n```\ntokens = purchase_amount × cashback_rate / 100\n```\n\nEach program has a default `cashback_rate` (e.g. 5%). You can override it per request."},{"id":"skill:11-earn-points#149","source":"skill:11-earn-points","title":"Skill 11 — Step 1: Get Program Info","text":"List your programs to find the `token_address` and current `cashback_rate`:\n\n```bash\ncurl -H \"x-api-key: lsk_...\" \\\n  \"https://api.loyalspark.online/agent-api/programs\"\n```"},{"id":"skill:11-earn-points#150","source":"skill:11-earn-points","title":"Skill 11 — Step 2: Earn Points via REST API","text":"```bash\ncurl -X POST \\\n  \"https://api.loyalspark.online/agent-api/earn\" \\\n  -H \"x-api-key: lsk_...\" \\\n  -H \"Content-Type: application/json\" \\\n  -d '{\n    \"token_address\": \"0xYourTokenAddress\",\n    \"customer_address\": \"0xCustomerWallet\",\n    \"purchase_amount\": 50\n  }'\n```\n\nOptional: override cashback rate for this request:\n```json\n{\n  \"token_address\": \"0x...\",\n  \"customer_address\": \"0x...\",\n  \"purchase_amount\": 50,\n  \"cashback_rate\": 10\n}\n```"},{"id":"skill:11-earn-points#151","source":"skill:11-earn-points","title":"Skill 11 — Step 3: Execute On-chain Transactions (fee-first)","text":"Same as minting — the response returns a fee-first `calls[]` bundle:\n\n1. **`calls[0]` (`protocol_fee`)** — mint platform fee to `fee_wallet`. **Send first.**\n2. **`calls[1]` (`recipient_mint`)** — mint calculated tokens to the customer.\n\nSubmit in order, or atomically via EIP-5792 `wallet_sendCalls`. Then confirm the fee with\n`POST /agent-api/mint/confirm { obligation_id, fee_tx_hash }` (MCP: `confirm_mint_fee`).\nUnconfirmed obligations (5+ older than 60 minutes) block further mints with HTTP 402.\n\n**Response (shape):**\n```json\n{\n  \"earn\": {\n    \"purchase_amount\": 50,\n    \"cashback_rate\": 5,\n    \"tokens_earned\": 2.5\n  },\n  \"mint\": { \"id\": \"uuid\", \"amount\": 2.5, \"recipient_address\": \"0x...\", \"token_address\": \"0x...\" },\n  \"fee_percent\": 1.25,\n  \"fee_amount\": 0.03125,\n  \"fee_wallet\": \"0x5cc0Aa9ed773F413f81f78a62F2e94109CE26205\",\n  \"fee_obligation_id\": \"uuid\",\n  \"calls\": [\n    { \"to\": \"0xToken\", \"data\": \"0x40c10f19...\", \"value\": \"0x0\", \"purpose\": \"protocol_fee\" },\n    { \"to\": \"0xToken\", \"data\": \"0x40c10f19...\", \"value\": \"0x0\", \"purpose\": \"recipient_mint\" }\n  ],\n  \"message\": \"Customer earns 2.5 COFFEE tokens for a $50 purchase (5% cashback)...\",\n  \"contract\": {\n    \"token_address\": \"0x...\",\n    \"function\": \"mint(address,uint256)\",\n    \"chain\": \"Base (8453)\",\n    \"builder_code\": \"bc_wdmnog7m\"\n  }\n}\n```\n\n**MCP equivalent:** `earn_points` + `confirm_mint_fee` (same fee-first model)."},{"id":"skill:11-earn-points#152","source":"skill:11-earn-points","title":"Skill 11 — Step 4: Verify Balance","text":"```bash\ncurl -H \"x-api-key: lsk_...\" \\\n  \"https://api.loyalspark.online/agent-api/balance?token_address=0x...&customer_address=0x...\"\n```"},{"id":"skill:11-earn-points#153","source":"skill:11-earn-points","title":"Skill 11 — Cashback Rate Examples","text":"| Purchase Amount | Cashback Rate | Tokens Earned |\n|----------------|---------------|---------------|\n| $10 | 5% | 0.5 |\n| $50 | 5% | 2.5 |\n| $100 | 10% | 10 |\n| $250 | 3% | 7.5 |"},{"id":"skill:11-earn-points#154","source":"skill:11-earn-points","title":"Skill 11 — Transaction Fees","text":"Same as regular minting — paid **in the loyalty tokens being minted**, not in USDC or fiat:\n\n| Plan | Commission (% of tokens minted) |\n|------|--------------------------------|\n| Free | 1.25% |\n| Pro | 0.5% |\n| Enterprise | 0.25% |"},{"id":"skill:11-earn-points#155","source":"skill:11-earn-points","title":"Skill 11 — Success Criteria","text":"- ✅ Tokens auto-calculated from purchase amount × cashback rate\n- ✅ Mint record created in database\n- ✅ Fee-first `calls[]` returned with builder code suffix\n- ✅ Fee obligation confirmed via `/agent-api/mint/confirm`\n- ✅ Customer balance updated after on-chain execution"},{"id":"skill:11-earn-points#156","source":"skill:11-earn-points","title":"Skill 11 — Next Skills","text":"- [Mint Tokens (manual)](./02-mint-tokens.md)\n- [Check Balance & Tiers](./05-balance-and-tiers.md)\n- [Manage Rewards](./04-manage-rewards.md)"},{"id":"skill:12-gift-certificates#157","source":"skill:12-gift-certificates","title":"Skill 12 — Goal","text":"Issue, manage and redeem **gift certificates** — pre-paid loyalty value identified by a 6-character `LOYAL-XXXXXX` code. A merchant agent issues the code (single or in batch), a recipient agent claims it, and the merchant mints loyalty tokens on-chain to the claimer's wallet."},{"id":"skill:12-gift-certificates#158","source":"skill:12-gift-certificates","title":"Skill 12 — Required Scopes","text":"- Merchant tools: `read` (list), `manage_rewards` (create, revoke), `mint` (mark minted)\n- Recipient tools: none beyond a valid `rwk_` key (recipient agent is wallet-bound)"},{"id":"skill:12-gift-certificates#159","source":"skill:12-gift-certificates","title":"Skill 12 — End-to-End Agent Flow","text":"1. **Merchant agent** issues a certificate\n   - MCP: `create_gift_certificate { token_address, usd_amount, points_per_dollar?, max_redemption_percent?, title?, description?, expires_in_days?, image_url?, quantity? (1–100) }`\n   - Returns one or many `{ id, code }` rows. Code format: `LOYAL-XXXXXX`.\n2. Merchant shares the code with the customer (QR, link, hand-out, etc.).\n3. **Recipient agent** previews the offer (optional)\n   - MCP: `lookup_gift_certificate { code }` — returns title, USD/token amount, merchant, expiry, status. No claim happens.\n4. **Recipient agent** claims it\n   - MCP: `claim_gift_certificate { code }` — binds the certificate to the agent's bound wallet, transitions `active → pending_mint`.\n5. Recipient shows the claim (or the wallet address) to the merchant.\n6. **Merchant agent** mints loyalty tokens on-chain\n   - MCP: `mint_loyalty_tokens { token_address, recipient: <claimer_wallet>, amount: <token_amount from certificate> }`\n   - Submit returned calldata + fee tx.\n7. **Merchant agent** marks the certificate as minted\n   - MCP: `mark_gift_certificate_minted { certificate_id, transaction_hash }` — transitions `pending_mint → redeemed` and stores the mint tx.\n8. **Recipient agent** can list its claims any time\n   - MCP: `list_my_gift_certificates { status?, limit? }`"},{"id":"skill:12-gift-certificates#160","source":"skill:12-gift-certificates","title":"Skill 12 — Lifecycle","text":"```\n[create_gift_certificate] → status=active\n        ↓ (recipient: claim_gift_certificate)\nstatus=pending_mint, redeemed_by=<wallet>, redeemed_at=now\n        ↓ (merchant: mint_loyalty_tokens on-chain)\n        ↓ (merchant: mark_gift_certificate_minted with tx_hash)\nstatus=redeemed, mint_tx_hash=0x…\n```\n\nOther terminal states: `revoked` (merchant `revoke_gift_certificate` while still `active`), `expired` (past `expires_at`)."},{"id":"skill:12-gift-certificates#161","source":"skill:12-gift-certificates","title":"Skill 12 — REST / Pay-per-call","text":"All tools above are also reachable via the paid x402 corridor:\n\n- Merchant: `POST https://api.loyalspark.online/x402-gateway/mcp-tools/<tool_name>` with `x-api-key: lsk_…`\n- Recipient: `POST https://api.loyalspark.online/x402-gateway/recipient-mcp-tools/<tool_name>` with `x-api-key: rwk_…`\n\nBody is standard MCP JSON-RPC `tools/call` (`{\"jsonrpc\":\"2.0\",\"id\":1,\"method\":\"tools/call\",\"params\":{\"name\":\"<tool>\",\"arguments\":{…}}}`). USDC on Base settles the 402 challenge."},{"id":"skill:12-gift-certificates#162","source":"skill:12-gift-certificates","title":"Skill 12 — MCP Tools Used","text":"- Merchant: `create_gift_certificate`, `list_gift_certificates`, `revoke_gift_certificate`, `mark_gift_certificate_minted`, `mint_loyalty_tokens`\n- Recipient: `lookup_gift_certificate`, `claim_gift_certificate`, `list_my_gift_certificates`"},{"id":"skill:12-gift-certificates#163","source":"skill:12-gift-certificates","title":"Skill 12 — Notes","text":"- `usd_amount * points_per_dollar` defines the token amount minted on redemption.\n- `max_redemption_percent` (5–100) governs how much of any future purchase the customer can pay with these tokens.\n- `quantity` allows batch issuance (1–100) for promotional drops; each row gets a unique `LOYAL-XXXXXX` code.\n- A revoked or expired certificate cannot be claimed; an already-claimed one cannot be re-claimed."},{"id":"skill:13-endpoint-workflows#164","source":"skill:13-endpoint-workflows","title":"Skill 13 — Goal","text":"Teach AI agents how to compose Loyal Spark endpoints into complete business flows instead of calling isolated routes out of order."},{"id":"skill:13-endpoint-workflows#165","source":"skill:13-endpoint-workflows","title":"Skill 13 — When to Use","text":"- You know the endpoint name, but not the required follow-up steps\n- You need to decide what to call next after a successful response\n- You want to safely automate merchant or recipient operations end-to-end"},{"id":"skill:13-endpoint-workflows#166","source":"skill:13-endpoint-workflows","title":"Skill 13 — Core Rules","text":"0. **External agents choose every value.**\n   Loyal Spark workflow responses tell you *what to call next* and which fields are required. They do **not** assign your program name, symbol, or reward catalog. Pass explicit `name`, `symbol`, `cost`, and `amount` on write endpoints. `auto_generate` exists only for trusted internal automation — external agents should omit it.\n\n1. **Do not treat one endpoint as the whole workflow.**\n   Many Loyal Spark operations are multi-step: prepare onchain calldata, broadcast, wait for confirmation, then update database state or call the next endpoint.\n\n2. **Always identify the actor first.**\n   - Merchant / issuer agent: `lsk_`\n   - Recipient / holder agent: `rwk_`\n\n   Use workflow-aware helpers first when available:\n   - Merchant REST: `GET /workflow/program-status`, `POST /workflow/generate-program-defaults`\n   - Merchant MCP: `get_program_workflow_status`, `generate_program_defaults`\n   - Recipient REST: `GET /recipient-api/workflow/reward-status`, `POST /recipient-api/workflow/prepare-reward-redemption`\n   - Recipient MCP: `get_reward_workflow_status`, `prepare_reward_redemption`\n\n3. **Always identify the program first.**\n   Before minting, rewards, vouchers, analytics, or transfers, determine:\n   - `token_address`\n   - `token_standard` (`b20` or `erc20`)\n   - `status`\n   - `merchant_address`"},{"id":"skill:13-endpoint-workflows#167","source":"skill:13-endpoint-workflows","title":"Skill 13 — Core Rules (2)","text":"4. **B20 is the default for new programs.**\n   - `b20`: Base-native Asset precompile, one deploy tx, active immediately after `register-program`\n   - `erc20`: legacy Loyal Spark path, requires explicit activation flow\n   - B20 remains ERC-20-compatible for the existing balance, transfer, allowance, mint, escrow, and voucher interfaces\n\n5. **Onchain-first operations need confirmation before follow-up.**\n   If a response returns calldata or depends on a tx hash, broadcast the tx, wait for confirmation, then continue."},{"id":"skill:13-endpoint-workflows#168","source":"skill:13-endpoint-workflows","title":"Skill 13 — 1. Create a New Loyalty Program","text":"Use when a merchant wants a fresh loyalty token.\n\n#### B20 default flow\n1. **You choose** program identity and economics:\n   - `name` (required)\n   - `symbol` (required)\n   - `expiration_days`, `cashback_rate`, `points_per_dollar` (optional)\n   - reward `name`, `description`, `cost` when creating catalog items\n2. Optional planner (does not set values for you):\n   - REST: `POST /workflow/generate-program-defaults`\n   - MCP: `generate_program_defaults`\n   Returns `field_catalog`, `workflow.next_actions`, and non-binding `examples`.\n3. Call:\n   - REST: `POST /programs`\n   - MCP: `create_loyalty_program`\n4. Broadcast returned `createB20(...)` calldata on Base.\n5. Extract `token_address` from:\n   - `B20Created` event, or\n   - `GET /tx-receipt?tx_hash=...`\n6. Call:\n   - REST: `POST /register-program`\n   - MCP: `register_loyalty_program`\n   with `token_standard: \"b20\"`\n7. Program is now **active**.\n8. Recommended next step: create at least one reward before minting at scale.\n\n##### Step 5 in full: `GET /tx-receipt` (free)\n\n```bash\ncurl -H \"x-api-key: lsk_YOUR_KEY\" \\\n  \"https://api.loyalspark.online/agent-api/tx-receipt?tx_hash=0xDEPLOY_TX_HASH\"\n```\n\n```json\n{\n  \"tx_hash\": \"0xDEPLOY_TX_HASH\",\n  \"status\": \"success\",\n  \"token_address\": \"0xYourNewLoyaltyToken\",\n  \"block_number\": 24500001,\n  \"gas_used\": 512345,\n  \"logs_count\": 3\n}\n```"},{"id":"skill:13-endpoint-workflows#169","source":"skill:13-endpoint-workflows","title":"Skill 13 — 1. Create a New Loyalty Program (2)","text":"- 400 — `tx_hash` is not a 32-byte hex hash.\n- 404 `Transaction not found or not yet confirmed` — still pending, poll every ~3 s; never re-deploy.\n- `status: \"failed\"` — the deploy reverted, do not register that address.\n- Handles B20 (`B20Created`) and legacy ERC-20 (`LoyaltyTokenCreated`) deploys.\n\n##### Step 6 in full: `POST /register-program`\n\n```bash\ncurl -X POST -H \"x-api-key: lsk_YOUR_KEY\" -H \"Content-Type: application/json\" \\\n  -d '{\"name\":\"Coffee Club\",\"symbol\":\"BREW\",\"token_address\":\"0xYourNewLoyaltyToken\",\"token_standard\":\"b20\"}' \\\n  https://api.loyalspark.online/agent-api/register-program\n```\n\n##### Optional: tune earn economics with `POST /update-program-config` ($0.005)\n\n```bash\ncurl -X POST -H \"x-api-key: lsk_YOUR_KEY\" -H \"Content-Type: application/json\" \\\n  -d '{\"token_address\":\"0xYourNewLoyaltyToken\",\"cashback_rate\":5,\"points_per_dollar\":10}' \\\n  https://api.loyalspark.online/agent-api/update-program-config\n```\n\n```json\n{ \"program\": { \"cashback_rate\": 5, \"points_per_dollar\": 10, \"status\": \"active\" }, \"message\": \"Program economics updated\" }\n```"},{"id":"skill:13-endpoint-workflows#170","source":"skill:13-endpoint-workflows","title":"Skill 13 — 1. Create a New Loyalty Program (3)","text":"- Scope `mint` or `create_program`; 404 when the program is not owned by the key's wallet.\n- At least one of `cashback_rate` / `points_per_dollar` is required, otherwise 400.\n- Database-only — no onchain transaction, no wallet signature.\n- Applies to later `POST /earn` calls: `points = amount × (cashback_rate / 100) × points_per_dollar`.\n\n##### Running the same two calls pay-per-call (x402)\n\nSwap `/agent-api/` for `/x402-gateway/`. The first response is HTTP 402 with `accepts[]` (USDC on Base, asset `0x833589fCD6eDb6E08f4c7C32D4f71b54bdA02913`); repeat the identical request with the signed `X-PAYMENT` header to execute. `/tx-receipt` is priced `0` on the gateway, `/update-program-config` is $0.005. Plain HTTP is redirected to HTTPS (308) before any payment challenge is issued, so always call the `https://` URL.\n\n#### Legacy ERC-20 flow\n1. Call create with `token_standard: \"erc20\"`.\n2. Broadcast factory deploy tx.\n3. Extract `token_address`.\n4. Register program with `token_standard: \"erc20\"`.\n5. Call:\n   - REST: `POST /activate-program`\n   - MCP: `activate_loyalty_program`\n6. Broadcast returned activation txs.\n7. Call:\n   - REST: `POST /program-status`\n   - MCP: `update_program_status`\n   with `status: \"active\"`"},{"id":"skill:13-endpoint-workflows#171","source":"skill:13-endpoint-workflows","title":"Skill 13 — 2. Create a Reward Catalog","text":"Use when a merchant wants the program to have redeemable utility.\n\n1. Confirm program exists and is active.\n2. Optionally inspect current rewards:\n   - REST: `GET /rewards`\n   - MCP: `list_rewards`\n3. Create reward:\n   - REST: `POST /rewards`\n   - MCP: `create_reward`\n4. Recommended reward fields:\n   - clear name\n   - concise description\n   - token cost aligned to earn rate"},{"id":"skill:13-endpoint-workflows#172","source":"skill:13-endpoint-workflows","title":"Skill 13 — 3. Mint Loyalty Tokens","text":"Use only after the program is active.\n\n1. Confirm merchant owns the program:\n   - REST: `GET /programs`\n   - MCP: `list_loyalty_programs`\n2. Confirm active state:\n   - `b20`: active after register\n   - `erc20`: active only after activation flow\n3. Choose one:\n   - `POST /mint` / `mint_loyalty_tokens`\n   - `POST /earn` / `earn_points` when mint amount depends on purchase amount\n4. Broadcast returned calldata if the route returns unsigned tx data.\n5. Verify result:\n   - `GET /balance`\n   - `GET /customers`\n   - recipient balance endpoints"},{"id":"skill:13-endpoint-workflows#173","source":"skill:13-endpoint-workflows","title":"Skill 13 — 4. Transfer Tokens","text":"#### Merchant-side transfer\n1. Confirm merchant controls the program.\n2. Call:\n   - REST: `POST /transfer`\n   - MCP: `transfer_loyalty_tokens`\n3. Broadcast calldata.\n4. Verify recipient balance.\n\n#### Recipient-side transfer\n1. Confirm holder has balance:\n   - REST: `GET /recipient-api/balance`\n   - MCP: `get_my_loyalty_balance`\n2. Call:\n   - REST: `POST /recipient-api/prepare-transfer`\n   - MCP: `prepare_loyalty_token_transfer`\n3. Holder signs and broadcasts calldata."},{"id":"skill:13-endpoint-workflows#174","source":"skill:13-endpoint-workflows","title":"Skill 13 — 5. Redeem Reward into Voucher","text":"This is always a multi-step flow.\n\n1. Discover reward:\n   - merchant: `GET /rewards`\n   - recipient: `GET /recipient-api/rewards`\n2. Prefer helper endpoints/tools to get merchant target address and ready-to-broadcast calldata.\n3. Transfer the required token amount onchain to the merchant.\n4. Wait for confirmation.\n5. Call:\n   - merchant REST/MCP reward redemption route\n   - recipient reward redemption route if acting as holder\n   passing the onchain `transaction_hash`\n6. Receive voucher code.\n7. Merchant later marks it used:\n   - REST: `POST /vouchers/use`\n   - MCP: `use_voucher`"},{"id":"skill:13-endpoint-workflows#175","source":"skill:13-endpoint-workflows","title":"Skill 13 — 6. Marketplace / P2P Offers","text":"1. Inspect existing offers:\n   - merchant or recipient offer list endpoint\n2. Create offer:\n   - prepare escrow calldata\n   - approve escrow if needed\n   - broadcast\n3. Accept or cancel with the corresponding endpoint.\n4. Do not assume offer finality until onchain execution confirms."},{"id":"skill:13-endpoint-workflows#176","source":"skill:13-endpoint-workflows","title":"Skill 13 — 7. Gift Certificates","text":"1. Merchant creates certificate metadata.\n2. Recipient claims certificate.\n3. Merchant marks it minted if onchain issuance is required.\n4. Treat gift certificates as a separate flow from vouchers."},{"id":"skill:13-endpoint-workflows#177","source":"skill:13-endpoint-workflows","title":"Skill 13 — Endpoint-to-Workflow Hints","text":"| Endpoint / Tool | Meaning in workflow |\n| --- | --- |\n| `POST /programs` / `create_loyalty_program` | Start deploy flow, not finish it |\n| `POST /workflow/generate-program-defaults` / `generate_program_defaults` | Fill in missing merchant identity, program naming, starter rewards, and economics |\n| `GET /workflow/program-status` / `get_program_workflow_status` | Ask the platform what is missing before issuing rewards or minting |\n| `GET /tx-receipt` | Extract deployed token address after tx |\n| `POST /register-program` | Persist program after deploy |\n| `POST /activate-program` | Only meaningful for legacy `erc20` |\n| `POST /program-status` | DB sync after legacy activation or pause changes |\n| `POST /rewards` | Usually comes after program creation, before large-scale minting |\n| `POST /mint` | Requires active program |\n| `POST /earn` | Same as mint, but purchase-driven |\n| `POST /redeem-reward` | Comes after confirmed onchain token transfer |\n| `GET /recipient-api/workflow/reward-status` / `get_reward_workflow_status` | Explain whether a holder can redeem now and what is missing |\n| `POST /recipient-api/workflow/prepare-reward-redemption` / `prepare_reward_redemption` | Build the transfer prerequisite before redeeming a reward |\n| `POST /vouchers/use` | Final merchant-side voucher step |"},{"id":"skill:13-endpoint-workflows#178","source":"skill:13-endpoint-workflows","title":"Skill 13 — Decision Rules for Agents","text":"- If the user asks to \"launch a program\", do **not** stop at deploy calldata.\n- If the user asks to \"make the loyalty program usable\", ensure:\n  - program exists\n  - program is active\n  - at least one reward exists\n- If the user asks to \"reward customers\", verify the program first.\n- If the user asks to \"redeem\", expect an onchain transfer step.\n- If the agent only has a recipient key (`rwk_`), do not use merchant-only endpoints."},{"id":"skill:13-endpoint-workflows#179","source":"skill:13-endpoint-workflows","title":"Skill 13 — Payment selection","text":"- Fixed-price per-call requests: use x402 v2 `exact` with USDC on Base, after validating the 402 requirements.\n- Tempo-native machine payments: use MPP with its published Tempo currency.\n- Recurring usage: use the agent subscription paid in USDC on Base.\n- The current gateways do **not** expose `upto`, partial capture, void, refund, payout, or split operations. Do not emulate those flows."},{"id":"skill:13-endpoint-workflows#180","source":"skill:13-endpoint-workflows","title":"Skill 13 — Success Criteria","text":"- The agent knows the next required step after every lifecycle endpoint\n- The agent distinguishes B20 Asset from legacy `erc20`\n- The agent does not mint into inactive or expired programs\n- The agent does not try to redeem rewards before onchain payment confirmation\n- The agent chooses a payment rail based on the actual published scheme"},{"id":"skill:14-b20-native-spec#181","source":"skill:14-b20-native-spec","title":"Skill 14 — Goal","text":"Understand what a Loyal Spark **B20** loyalty token actually is at the chain level, so an agent can reason about roles, policies, pausing, memos and permits without guessing.\n\nSource of truth: Base docs → `/specifications/b20/specification-overview` (\"Beryl\" spec). Loyal Spark deploys the **Asset** variant."},{"id":"skill:14-b20-native-spec#182","source":"skill:14-b20-native-spec","title":"Skill 14 — Required Scope","text":"`read` (informational) — writes below still need `mint` / `create_program`."},{"id":"skill:14-b20-native-spec#183","source":"skill:14-b20-native-spec","title":"Skill 14 — 1. Deployment model","text":"- B20 is an **ERC-20 superset implemented as chain-native Rust precompiles** — no custom contract, no audit surface, no proxy.\n- Every token is created through the singleton **factory precompile**:\n  `createB20(uint8 variant, bytes32 salt, bytes params, bytes[] initCalls)` at\n  `0xB20f000000000000000000000000000000000000` (same address on Base Mainnet 8453 and Sepolia 84532).\n- Address is deterministic: `getB20Address(variant, sender, salt)` — an agent can precompute the token address **before** broadcasting.\n- `isB20(token)` returns whether an arbitrary address is a native B20.\n- Variants: `0 = Asset` (used by Loyal Spark loyalty points), `1 = Stablecoin`.\n- `initCalls` run atomically inside the deploy tx. Loyal Spark uses them to grant `MINT_ROLE` to the merchant admin **and** the agent's CDP wallet in the same transaction (`extra_minters`)."},{"id":"skill:14-b20-native-spec#184","source":"skill:14-b20-native-spec","title":"Skill 14 — 2. Roles","text":"| Role | Meaning for a loyalty program |\n|------|-------------------------------|\n| `DEFAULT_ADMIN` | Merchant owner; grants/revokes every other role |\n| `MINT` | Issues points (merchant wallet + agent CDP wallet) |\n| `BURN` | Redemption / expiry burns |\n| `SEIZE` | Compliance clawback (unused by default) |\n| `PAUSE` / `UNPAUSE` | Freeze a specific feature (see §4) |\n| `METADATA` | Update name / symbol / `contractURI` (ERC-7572) |\n| `OPERATOR` | Asset-variant only: multiplier / split / announcements |\n\n`MINT_ROLE = keccak256(\"MINT_ROLE\")` = `0x154c00819833dac601ee5ddded6fda79d9d8b506b911b3dbd54cdb95fe6c3686`.\n\nAdmin exit rules:\n- The **last** admin can only leave via `renounceLastAdmin()`.\n- Deploying with `initialAdmin == address(0)` launches the token **admin-less** (immutable) — Loyal Spark never does this for merchant programs, because expiry burns and role grants would become impossible."},{"id":"skill:14-b20-native-spec#185","source":"skill:14-b20-native-spec","title":"Skill 14 — 3. Policies (PolicyRegistry precompile)","text":"- Policies live in a **singleton PolicyRegistry**, referenced by `uint64` id encoded as `[8-bit PolicyType][56-bit counter]`.\n- Types: `BLOCKLIST`, `ALLOWLIST`, `UNION`, `INTERSECT`.\n- Built-ins: `ALWAYS_ALLOW = 0`, `ALWAYS_BLOCK = (ALLOWLIST << 56) | 1`.\n- Token scopes that can point at a policy: `TRANSFER_SENDER`, `TRANSFER_RECEIVER`, `TRANSFER_EXECUTOR`, `MINT_RECEIVER`, `SEIZE_HOLDER`, `SEIZE_RECEIVER`.\n- **Default for Loyal Spark programs: `ALWAYS_ALLOW` on every scope** — loyalty points stay freely transferable, so the P2P escrow marketplace and voucher flows work unchanged.\n- `approve` / `permit` are **not** policy-gated; only the transfer itself is.\n- Admin transfer of a policy is two-step; `renounceAdmin` freezes the policy permanently.\n\n> Agent rule: if a transfer reverts on a B20 program, check the policy id on `TRANSFER_SENDER`/`TRANSFER_RECEIVER` before assuming a balance problem."},{"id":"skill:14-b20-native-spec#186","source":"skill:14-b20-native-spec","title":"Skill 14 — 4. Granular pause","text":"Pause is per `PausableFeature`, not global: `TRANSFER`, `MINT`, `BURN`, `SEIZE`.\nA merchant can stop issuance (pause `MINT`) while customers keep spending existing points (`TRANSFER` still live). Loyal Spark's program-expiry logic is enforced in the backend (`check_program_expiration()`), not by pausing."},{"id":"skill:14-b20-native-spec#187","source":"skill:14-b20-native-spec","title":"Skill 14 — 5. Memos — optional onchain attribution","text":"B20 adds memo-carrying variants: `transferWithMemo`, `mintWithMemo`, `burnWithMemo`, …\n\n- Each emits `Memo(address caller, bytes32 memo)` **immediately after** the primary `Transfer` event.\n- Indexers join by `(txHash, logIndex - 1)`.\n- Use for order ids, voucher codes, campaign ids: `memo = keccak256(\"order:12345\")` or a 32-byte raw ASCII tag.\n\nLoyal Spark currently emits standard `mint` / `transfer` calldata (no memo). The public API does not currently accept a `memo` field; a first-class memo request is a roadmap item. Agents must not claim memo attribution was recorded unless the returned calldata explicitly identifies a memo variant."},{"id":"skill:14-b20-native-spec#188","source":"skill:14-b20-native-spec","title":"Skill 14 — 6. Other spec facts worth knowing","text":"- **Supply cap**: `type(uint128).max` means \"no cap\". Loyal Spark leaves loyalty programs uncapped.\n- **ERC-2612 permit**: EIP-712 domain version is `\"1\"`. **ERC-1271 (smart-contract) signatures are NOT accepted** for permit — an agent using a Base Account / smart wallet must call `approve` in a normal transaction instead of gasless permit.\n- **ERC-7572** `contractURI` carries program branding.\n- B20 is fully ERC-20 compatible: `balanceOf`, `transfer`, `transferFrom`, `allowance` behave exactly as agents expect, so every existing Loyal Spark read path (balances, tiers, escrow, vouchers) is unchanged."},{"id":"skill:14-b20-native-spec#189","source":"skill:14-b20-native-spec","title":"Skill 14 — 7. Network facts","text":"- Base Mainnet chainId **8453**, RPC `https://mainnet.base.org`, explorer `basescan.org`.\n- **Flashblocks**: ~200 ms preconfirmations, sub-second confirmation, sub-cent fees. Agents should poll receipts at ~250–500 ms rather than the 2 s default of most SDKs.\n- **Vibenet** is Base's demo network used in docs examples — Loyal Spark does **not** deploy there; use Base Sepolia (84532) for testing."},{"id":"skill:14-b20-native-spec#190","source":"skill:14-b20-native-spec","title":"Skill 14 — Success criteria","text":"- Agent can explain why a B20 transfer reverted (policy vs balance vs pause).\n- Agent knows memo variants exist, but does not claim Loyal Spark recorded a memo unless returned calldata explicitly says so.\n- Agent never attempts ERC-1271 permit against a B20 and uses normal `approve` for smart accounts."},{"id":"skill:14-b20-native-spec#191","source":"skill:14-b20-native-spec","title":"Skill 14 — Next skills","text":"- [Create Loyalty Program](./01-create-loyalty-program.md)\n- [Mint Tokens](./02-mint-tokens.md)\n- [Payment Scenarios](./15-payment-scenarios.md)"},{"id":"skill:15-payment-scenarios#192","source":"skill:15-payment-scenarios","title":"Skill 15 — Goal","text":"Pick and execute the right payment corridor when an agent has to pay Loyal Spark — per call, per usage, or per month — following the Base \"accept payments\" lifecycle."},{"id":"skill:15-payment-scenarios#193","source":"skill:15-payment-scenarios","title":"Skill 15 — Required Scope","text":"None for paying; the underlying tool still needs its own scope after settlement."},{"id":"skill:15-payment-scenarios#194","source":"skill:15-payment-scenarios","title":"Skill 15 — 0. Decide the corridor","text":"| Situation | Use |\n|-----------|-----|\n| Agent already has an `lsk_` / `rwk_` key and a plan | **API key** — no payment per call |\n| One-off call with a published fixed price | **x402 v2 `exact`** |\n| Harness speaks Machine Payments Protocol / Tempo | **MPP gateway** |\n| Recurring monthly quota and lower mint fee | **Agent plan subscription in USDC** |\n| Variable amount, partial capture, refund, payout, or split required | **Not currently exposed by Loyal Spark gateways** — do not emulate it |"},{"id":"skill:15-payment-scenarios#195","source":"skill:15-payment-scenarios","title":"Skill 15 — 1. Payment lifecycle (Base model)","text":"Base documents a broader lifecycle:\n\n```\nRequest → Authorize → Capture (full or partial) → Verify → Refund / Payout / Split\n                    ↘ Void\n```\n\nLoyal Spark currently exposes a narrower fixed-price request lifecycle:\n\n```\nRequest → 402 challenge → Authorize exact amount → Verify → Settle → Retry request\n```\n\n| Phase | Loyal Spark behaviour |\n|-------|----------------------|\n| **Request** | Call a mapped gateway route with no payment → HTTP **402** + payment requirements and Bazaar metadata |\n| **Authorize** | x402 client signs the exact advertised USDC amount on Base; MPP client obtains its Tempo payment credential |\n| **Capture / Settle** | x402 gateway verifies and settles the exact amount through the configured facilitator before proxying; MPP returns a receipt after its charge succeeds |\n| **Void** | Unknown route → **404**, no settlement. A failed settlement is a hard 402 and is not proxied upstream |\n| **Verify** | Inspect the payment response and upstream JSON separately; a settled payment does not turn a failed business operation into success |\n| **Refund / Payout / Split** | Not customer-callable operations in the current gateways. Subscription payment verification only activates the selected plan after a matching Base USDC transfer |"},{"id":"skill:15-payment-scenarios#196","source":"skill:15-payment-scenarios","title":"Skill 15 — 1. discover","text":"curl https://api.loyalspark.online/.well-known/x402"},{"id":"skill:15-payment-scenarios#197","source":"skill:15-payment-scenarios","title":"Skill 15 — 2. call (client SDK auto-pays on 402)","text":"POST https://api.loyalspark.online/x402-gateway/mint\nPOST https://api.loyalspark.online/x402-gateway/mcp-tools/<tool_name>     # merchant, lsk_\nPOST https://api.loyalspark.online/x402-gateway/recipient-mcp-tools/<n>   # holder, rwk_\n```\n\n- Currency: **USDC on Base** `0x833589fCD6eDb6E08f4c7C32D4f71b54bdA02913`, CAIP-2 `eip155:8453`.\n- Use `@x402/fetch` (or any x402 client) so the 402 → sign → retry loop is automatic.\n- Prices per tool: `_shared/mcp-bazaar-tools.ts` (merchant) and `_shared/recipient-mcp-bazaar-tools.ts` (holder)."},{"id":"skill:15-payment-scenarios#198","source":"skill:15-payment-scenarios","title":"Skill 15 — 3. Variable-charge boundary","text":"The public x402 gateway advertises `scheme: \"exact\"` for fixed route prices. It does **not** expose `scheme: \"upto\"`, metered capture, or a variable-price batch operation. Bulk work is represented by the route's published fixed price and normal request validation; never invent an `upto` payload or sign more than the server's exact requirement.\n\nThe same boundary applies to MPP: use the challenge and credential format returned by the MPP gateway, not x402 payload fields."},{"id":"skill:15-payment-scenarios#199","source":"skill:15-payment-scenarios","title":"Skill 15 — 4. Spend policies (before signing anything)","text":"Check these client-side, in this order, before every payment:\n\n1. **Per-call cap** — reject if `maxAmountRequired` exceeds your ceiling.\n2. **Per-session / daily budget** — accumulate settled amounts and stop at the budget.\n3. **Asset + network allowlist** — only USDC on `eip155:8453` (or pathUSD on Tempo for MPP). Refuse anything else.\n4. **Recipient allowlist** — the `payTo` address must match the one published at `https://api.loyalspark.online/.well-known/x402`.\n5. **Idempotency** — retries after a network error must reuse the same authorization, never sign a fresh one."},{"id":"skill:15-payment-scenarios#200","source":"skill:15-payment-scenarios","title":"Skill 15 — 5. MPP corridor","text":"- Gateway: `https://api.loyalspark.online/mpp-gateway`\n- Currency: **pathUSD on Tempo** (USDC also accepted).\n- Manifest: `https://loyalspark.online/.well-known/mpp.json`\n- Same 404-on-unknown-route and hard settlement gate as x402."},{"id":"skill:15-payment-scenarios#201","source":"skill:15-payment-scenarios","title":"Skill 15 — 6. Subscriptions (best value for recurring agents)","text":"Pay once a month in USDC on Base instead of per call:\n\n| Plan | Price | API calls/mo | Agents | Mint fee |\n|------|-------|--------------|--------|----------|\n| Free | $0 | 200 | 1 | 1,000 tokens/mo · 1.25% |\n| Pro | $49 USDC | 10,000 | 5 | 0.5% |\n| Enterprise | $129 USDC | Unlimited | Unlimited | 0.25% |\n\nFlow: `https://loyalspark.online/for-agents/subscribe` → pick plan → pay USDC on Base → the tx hash is verified automatically (polling); if verification lags, call the billing endpoint action `retry_verification`.\n\nThe **mint fee is paid in your own loyalty tokens** (an extra `mint()` to the platform fee wallet), not in USDC. Only subscriptions and x402 / MPP calls are USDC."},{"id":"skill:15-payment-scenarios#202","source":"skill:15-payment-scenarios","title":"Skill 15 — 7. High-frequency usage","text":"For many small charges, prefer a subscription and use the API key — the plan limits and mint commission are enforced server-side. If using pay-per-call, pay each published route price independently and reuse the same authorization only for a network retry of that same request."},{"id":"skill:15-payment-scenarios#203","source":"skill:15-payment-scenarios","title":"Skill 15 — Success criteria","text":"- Agent never signs a payment that violates its own spend policy.\n- x402 requests use the server-advertised `exact` amount and asset.\n- MPP requests use the MPP challenge/credential flow.\n- Subscription is chosen once monthly volume and plan entitlements justify it.\n- Agent does not claim `upto`, refund, payout, split, or partial capture support."},{"id":"skill:15-payment-scenarios#204","source":"skill:15-payment-scenarios","title":"Skill 15 — Next skills","text":"- [Getting Started](./00-getting-started.md)\n- [B20 Native Spec](./14-b20-native-spec.md)\n- [Endpoint Workflows](./13-endpoint-workflows.md)"},{"id":"pricing#205","source":"pricing","title":"Monetization & public pricing — Loyal Spark","text":"This document is the **single source of truth** for public pricing: it reflects product docs, the marketing narrative, positioning vs regional benchmarks (e.g. UDS for Russia GTM), separate axes for **merchant SaaS** vs **AI agents**, pay-per-call (x402 / MPP), and explicit risks.\n\n**Origin:** Product request to design platform monetization based on existing project documentation and the public product story.\n\n**Implementation:** Agent plans are enforced in `agent_plans` + `verify-agent-plan-payment`. Merchant plans are enforced in `merchant_plans` + `merchant_plan_subscriptions` + the same Edge Function (see **Payment settlement** below).\n\n---"},{"id":"pricing#206","source":"pricing","title":"1. Principles","text":"1. **Two pricing axes (do not merge without explanation)**  \n   - **Merchant** — portal access, humans, programs, CRM-light.  \n   - **Agents** — API + MCP, `lsk_` keys, automation.  \n   Pro agent pricing **above** merchant Starter is intentional (R&D / integration vs one operator seat).\n\n2. **Cash revenue today comes from prepaid rails only** — agent/merchant **subscriptions in USDC** and **x402 / MPP per-request** payments. Both are collected *before* the service is delivered and cannot be skipped.\n\n   The **mint fee %** is **not** a cash revenue line today: it is settled in the **merchant's own loyalty tokens**, and it is enforced **off-chain**. Treat it as protocol accounting and a future lever, not as ARR. See [§3.1](#31-what-the-mint-fee-actually-is) before putting it in any financial model.\n\n3. **Globally** anchor on **SMB SaaS for on-chain loyalty**; UDS is a regional reference, not a feature checklist.\n\n4. **Regulatory modes:** Where secondary trading of loyalty tokens is restricted, product routes (DEX / marketplace) may be off; **USD price list** stays one column — local acquiring is a **payment rail**, not a second price list.\n\n---"},{"id":"pricing#207","source":"pricing","title":"2. Merchant SaaS (portal)","text":"| Plan | USD / month | Role |\n|------|-------------|------|\n| **Starter** | **$39** | SMB entry |\n| **Growth** | **$79** | Upsell for scale and depth. Includes in-app **Merchant Concierge** (Loyal Spark–only) + Analyst reports. |\n| **Scale** | **$149** | Corporate-style budgets and priority. Concierge + priority ops routing; dedicated onboarding. |\n\n**Annual billing (optional):** **15–20%** off vs 12× monthly — typical B2B SaaS.\n\n**Honest positioning:** Do not claim parity with UDS on features you have not shipped (e.g. white-label mobile app). Compete on **on-chain programs + agents + transparency** at a **comparable loyalty/CRM-light** price point."},{"id":"pricing#208","source":"pricing","title":"2.1 In-app AI assistants (OpenServ Concierge)","text":"- Protocol pays OpenServ; assistants **refuse off-topic** (weather, general chat, etc.).\n- Runtime: Edge `chat-bridge` + hosted Concierge agents — see [OPENSERV_STAGES_BCD.md](../integrations/OPENSERV_STAGES_BCD.md).\n- Not a substitute for agent API plans (`lsk_` / `rwk_`); portal Concierge is a merchant/shopper UX surface.\n\n---"},{"id":"pricing#209","source":"pricing","title":"3. AI agents (API + MCP, `lsk_` keys)","text":"| Plan | USD / month | API calls / month | Agents | Mint fee (% of mint amount) |\n|------|-------------|-------------------|--------|-----------------------------|\n| **Free** | **$0** | **200** | **1** | **1.25%** |\n| **Pro** | **$49** | **10 000** | **5** | **0.50%** |\n| **Enterprise** | **$129** | **Unlimited** | **Unlimited** | **0.25%** |\n\n**Free @ 1.25%:** Slightly higher than 1% to offset a more generous free tier and reduce toxic micro-spam; monitor **COGS** if limits increase.\n\nSubscriptions are paid in **USDC on Base** ($1 = 1 USDC) per current product flow.\n\n**Enforcement note (2026-08):** Monthly **API call** quotas, plan agent-seat limits, and the Free plan **1,000 tokens/mo** mint cap are enforced server-side in Edge Functions. Enterprise remains unlimited for agents and minting. Admin wallets listed by the platform bypass all plan limits."},{"id":"pricing#210","source":"pricing","title":"3.1 What the mint fee actually is","text":"Be precise about this everywhere — public copy, decks, and investor material.\n\n| Question | Answer today |\n|---|---|\n| What is charged? | A second `mint(address,uint256)` call on the **merchant's own loyalty token** |\n| Paid in what? | **Loyalty tokens** (the merchant's points) sent to `PLATFORM_FEE_WALLET` — **not** USDC, not ETH, not fiat |\n| Who enforces it? | The **API**, off-chain: `_shared/agent-fee-ledger.ts` records an obligation, verifies settlement from on-chain `Transfer`-from-zero logs, and blocks new mints after **5** unpaid obligations older than **60 min** |\n| Does the token contract enforce it? | **No.** There is no `mintWithFee`. A merchant holding mint rights can mint directly on-chain and pay nothing |\n| Can it be counted as revenue? | **No.** Loyalty points have no market price and the issuer can pause or expire the program |\n\nConsequences to respect:"},{"id":"pricing#211","source":"pricing","title":"3.1 What the mint fee actually is (2)","text":"- **Never** present the mint fee as USD/USDC revenue or as the primary growth lever.\n- **Never** claim it is \"onchain-enforced\", \"automatic\", \"guaranteed\", or \"unavoidable\". The accurate word is **accountability**.\n- Contract-level enforcement (`mintWithFee` or an equivalent fee-on-mint hook) is a **roadmap item**; it needs a new factory or an upgrade path plus an audit, and the default **B20 factory is not ours**.\n- Column `agent_usage.fees_collected_usdc` stores **token units**, not USDC — legacy name, do not read it as dollars.\n\n---"},{"id":"pricing#212","source":"pricing","title":"4. Pay-per-call (x402 / MPP)","text":"Public **corridor** (tune for gas + facilitator):\n\n| Type | USD range | Messaging |\n|------|-----------|-----------|\n| Read | **~$0.001–0.005** | “**From ~$0.002** per read” |\n| Write | **~$0.005–0.05** | Publish upper bound in API docs when stable |"},{"id":"pricing#213","source":"pricing","title":"4.1 Recipient agents (`rwk_`) — same corridor","text":"Buyer-side agents pay for paid routes when using **`mpp-gateway`** (MPP) or **`x402-gateway`** (USDC x402). Direct **`rwk_`** calls use the same free-tier **200 calls/mo** as `lsk_` (`agent_usage`).\n\n**REST** (`recipient-api/…` after the gateway prefix) — source: `supabase/functions/_shared/recipient-paid-routes.ts`:\n\n| Method | Route suffix | USD |\n|--------|----------------|-----|\n| GET | `recipient-api/me` | **0** |\n| GET | `recipient-api/balances`, `balance`, `rewards`, `vouchers`, `offers` | **0.001** |\n| POST | `recipient-api/register` | **0** |\n| POST | `recipient-api/prepare-transfer` | **0.005** (aligned with merchant `transfer`) |\n| POST | `recipient-api/redeem-reward`, `offers`, `accept-offer` | **0.01** |\n| POST | `recipient-api/cancel-offer` | **0.005** |\n\n**MCP** (x402 only; resource `recipient-mcp-tools/<tool>`) — source: `supabase/functions/_shared/recipient-mcp-bazaar-tools.ts`.  \nDiscovery (Coinbase **x402 Bazaar**): the gateway builds HTTP **402** `accepts` with `extensions.bazaar` and MCP-shaped `outputSchema` via `_shared/x402-bazaar-accept.ts` (same pattern as merchant `mcp-tools/*`)."},{"id":"pricing#214","source":"pricing","title":"4.1 Recipient agents (`rwk_`) — same corridor (2)","text":"| Tool | USD | Notes |\n|------|-----|--------|\n| `prepare_loyalty_token_transfer` | **0.005** | Same band as transfer calldata |\n| `list_p2p_offers` | **0.001** | Aligned with merchant GET `/offers` on MPP |\n| `cancel_p2p_offer` | **0.005** | Aligned with merchant cancel |\n| All other listed recipient tools | **0.01** | Same default as merchant MCP Bazaar tools |\n\n---"},{"id":"pricing#215","source":"pricing","title":"5. Payment settlement (both merchants & agents)","text":"- **Wallet:** `payment_settings.subscription_wallet_address` — **one** treasury address for **USDC on Base**.  \n- **Verification:** Edge Function `verify-agent-plan-payment`  \n  - `action: \"get_payment_info\"` + optional `product: \"agent\" | \"merchant\"` (default **`agent`**).  \n  - `action: \"verify_payment\"` + `product`, `plan_slug`, `owner_address`, `transaction_hash`.  \n- **On-chain check:** ERC-20 **Transfer** logs for USDC to the subscription wallet (BaseScan API when `BASESCAN_API_KEY` is set).\n\nMerchant and agent plans **share the same payout address**; they differ by **plan table** and **subscription row** (`agent_plan_subscriptions` vs `merchant_plan_subscriptions`).\n\n---"},{"id":"pricing#216","source":"pricing","title":"6. “Two bills” narrative (site copy)","text":"Use one schema everywhere:\n\n- **Merchant bill** = portal + people + programs.  \n- **Agent bill** = automation + integrations + API limits + lower mint %.\n\nWithout this split, conversion drops.\n\nWhen the agent bill is described, the **paid** part is the subscription and per-request calls; the lower mint % is a **benefit of the tier**, not a second invoice.\n\n---"},{"id":"pricing#217","source":"pricing","title":"7. Risks & caveats","text":"| Risk | Mitigation |\n|------|------------|\n| Drift between marketing and DB fees/limits | This doc + migrations; `agent_plans` / `merchant_plans` as truth. |\n| COGS on Free @ **200** calls | Monitor Edge/DB load; tighten fair-use if needed. |\n| Expectation of full UDS parity | Clear roadmap-only claims. |\n| Russia: friction paying USDC | Separate acquiring track **without** publishing a second USD ladder. |\n| **Mint fee read as cash revenue** | §3.1 wording is mandatory in decks and site copy; models rely on subscriptions + x402 only. |\n| **Mint fee bypassed by direct on-chain mint** | Accepted today — the fee is in points, so the loss is not cash. Off-chain ledger blocks repeat offenders; contract-level enforcement is roadmap. |\n\n---"},{"id":"pricing#218","source":"pricing","title":"Related","text":"- [ACTION_PLAN_MONETIZATION.md](./ACTION_PLAN_MONETIZATION.md) — sync checklist for code, DB, and production."},{"id":"portals#219","source":"portals","title":"Merchant & customer portals — UI, auth, and team invites","text":"Human-facing behaviour for `/merchant` and `/customer` (web and Capacitor shells). Keep this file aligned with `MerchantPage`, `CustomerPage`, `WalletConnectButton`, and team components."},{"id":"portals#220","source":"portals","title":"Routes","text":"| Path | Portal |\n|------|--------|\n| `/merchant` | Merchant Portal — programs, CRM, marketing, **Team**, AI Agents, etc. |\n| `/customer` | Customer Portal — loyalty balances, exchange tab, profile |\n\nNative wrapper routes may use the `/native/...` prefix; header behaviour is the same."},{"id":"portals#221","source":"portals","title":"Header action cluster (merchant & customer)","text":"Reading **left → right** in the top-right group:\n\n1. **Theme toggle** (light / dark)\n2. **Profile** — only when there is an active **Supabase session** (`useAuth().user`). Hidden while the user must sign in.\n3. **Wallet / Sign in** — Privy login, SIWE completion, or connected account chip (`WalletConnectButton`)\n\nDo not reorder this cluster without an explicit product decision."},{"id":"portals#222","source":"portals","title":"Sizing (implementation detail)","text":"- **Profile** uses a compact chip (`HEADER_PROFILE_BUTTON_CLASSNAME` in `WalletConnectButton.tsx`): same height as the wallet control, **auto width** so the label is not stretched.\n- **Sign in / Signing in… / address** use a fixed-width chip (`HEADER_CLUSTER_ACTION_CLASSNAME`) so truncated addresses line up.\n- In-card auth CTAs (`AuthPrompt`) share height/typography via `INLINE_AUTH_CTA_CLASSNAME`.\n- `Button` merges `className` **after** `buttonVariants({ variant, size })` so header overrides (e.g. `h-8`) always win — see `src/components/ui/button.tsx`."},{"id":"portals#223","source":"portals","title":"Merchant (`src/pages/MerchantPage.tsx`)","text":"- **Profile** button: rendered **only if `user`** (Supabase session).\n- Toggling profile uses local `showProfile`; on **sign-out**, `showProfile` is reset so the dashboard is not left on a profile-only layout."},{"id":"portals#224","source":"portals","title":"Customer (`src/pages/CustomerPage.tsx`)","text":"- Desktop **Profile** header button: same rule — **only if `user`**.\n- **Tabs:** `profile` **TabsContent** is not mounted until `user` exists.\n- **Mobile:** `BottomNavBar` receives `showProfileNav={Boolean(user)}` so the **Profile** nav item is hidden until signed in. If the user signs out while on profile, `activeTab` is forced back to **`loyalty`**.\n- `renderContent()` for mobile: `profile` returns `null` when there is no `user`."},{"id":"portals#225","source":"portals","title":"Owner (generate code)","text":"1. Open **`/merchant`** and sign in as the merchant owner.\n2. Go to the **Team** tab.\n3. Under **Team Members**, choose role / branch, then **Invite Code** (or equivalent) and **Generate Invite Code**.\n4. Send the code to the employee (short TTL; status `pending` in `merchant_invites`)."},{"id":"portals#226","source":"portals","title":"Employee / manager (redeem code)","text":"1. Open **`/merchant`**, sign in with the **same wallet** they will use at work (profile `wallet_address` must match the SIWE / session path expected by the backend).\n2. Open the **Team** tab.\n3. Use **Team invite code** → paste code → **Join team**.\n\nThis calls Supabase RPC **`public.accept_merchant_invite(p_invite_code text)`** (`SECURITY DEFINER`, `GRANT EXECUTE` to `authenticated`). Migrations live under `supabase/migrations/` (files containing `accept_merchant_invite`). If the API error mentions **schema cache** or the function is **not found**, the linked Supabase project has not applied those migrations.\n\n**RLS note:** non-owners cannot `INSERT` into `merchant_employees` directly; redemption must go through this RPC."},{"id":"portals#227","source":"portals","title":"Related source files","text":"| Area | Files |\n|------|--------|\n| Pages | `MerchantPage.tsx`, `CustomerPage.tsx` |\n| Header / wallet | `WalletConnectButton.tsx`, `ThemeToggle.tsx` |\n| Auth banners | `AuthPrompt.tsx` |\n| shadcn Button merge | `components/ui/button.tsx` |\n| Team UI | `merchant/tabs/TeamTab.tsx`, `team/EmployeeManagement.tsx`, `team/AcceptMerchantInviteCard.tsx`, `team/BranchManagement.tsx`, … |\n| Mobile nav | `mobile/BottomNavBar.tsx` |"},{"id":"portals#228","source":"portals","title":"Ops checklist (Lovable / CI / manual)","text":"1. After pulling UI that depends on new RPCs, run **`supabase db push`** (or your pipeline) so **production** Postgres matches `migrations/`.\n2. Confirm `accept_merchant_invite` exists: SQL Editor → `select proname from pg_proc join pg_namespace n on n.oid = pronamespace where n.nspname = 'public' and proname = 'accept_merchant_invite';`\n3. If `public/` assets were deleted locally but not committed, restore with `git restore public/` before shipping — see repo **README** / release process."},{"id":"guide#229","source":"guide","title":"Quick links","text":"].map(() => ( handleCardClick(tab)} role=\"button\" onKeyDown={(e) => }"},{"id":"guide#230","source":"guide","title":"What is Loyal Spark?","text":"The future of customer loyalty on blockchain Loyal Spark is a revolutionary loyalty platform that uses blockchain technology to give businesses and customers true ownership of rewards. Unlike traditional loyalty points that only exist in a company's database, Loyal Spark tokens are real digital assets stored on the blockchain."},{"id":"guide#231","source":"guide","title":"True Ownership","text":"Customers own their tokens directly in their wallet. No company can freeze or take them away."},{"id":"guide#232","source":"guide","title":"Real Value","text":"Tokens sit in the customer wallet and can be sent or swapped through P2P escrow — not a public DEX listing."},{"id":"guide#233","source":"guide","title":"Instant Transparency","text":"All transactions are recorded on the blockchain, creating an immutable and transparent history."},{"id":"guide#234","source":"guide","title":"Better Engagement","text":"Advanced CRM, tiers, automation, and analytics help businesses build lasting customer relationships."},{"id":"guide#235","source":"guide","title":"Why Blockchain?","text":"You Actually Own Your Rewards Traditional loyalty points are just entries in a company database. If the company changes terms or goes out of business, your points can disappear. Blockchain tokens are yours forever. Tokens Have Real Market Value Because they are onchain, customers can send them or swap them through Loyal Spark P2P escrow. That is wallet ownership, not a DEX market. Complete Transparency Every transaction is recorded on the public blockchain. You can verify exactly how many tokens were issued, to whom, and when - creating trust through transparency. No Single Point of Failure Unlike centralized systems, blockchain networks are distributed across thousands of computers. Your tokens are always accessible, even if a company's servers go down. Click \"Sign In\" to get started. You can use email, passkey, or connect a Web3 wallet like MetaMask or Coinbase Wallet."},{"id":"guide#236","source":"guide","title":"Free 45-day Trial — start instantly","text":"Every new merchant wallet automatically gets 45 days on the Growth plan (and every new AI agent gets 45 days on Pro What's included: marketing campaigns, automation rules, RFM segmentation, customer tiers, full CRM analytics, branded loyalty token deployment. How it starts: trial is created the first time you visit the Merchant portal — nothing to click. When it ends: paid features become read-only (your data stays visible). Renew with USDC on Base from Merchant → Billing Annual billing: save 15% on Starter / Pro and 20% on Growth / Scale / Enterprise. Already paid? Trial is skipped automatically — your active subscription wins."},{"id":"guide#237","source":"guide","title":"Step 1: Create Your Loyalty Program","text":"Sign in with email, passkey, or connect your wallet Navigate to the Merchant section Enter your token details: Token Name (e.g., \"Coffee Shop Rewards\") Symbol (e.g., \"COFFEE\") Initial Supply (how many tokens to create) Expiration date for the program Click \"Deploy Token\" and confirm the transaction in your wallet Wait for deployment (usually 1-2 minutes) Your token is now live on the blockchain! 🎉"},{"id":"guide#238","source":"guide","title":"Step 2: Create Rewards","text":"Rewards are what customers can redeem with their tokens. Examples: free coffee, discounts, exclusive products. Go to the \"Rewards\" tab Click \"Create New Reward\" Enter reward details: Name (e.g., \"Free Latte\") Description Cost in tokens (e.g., 50 COFFEE) Save the reward - customers can now see it in their rewards catalog"},{"id":"guide#239","source":"guide","title":"Step 3: Issue Tokens to Customers","text":"When a customer makes a purchase, reward them with tokens: Select your program from the dropdown Click \"Activate Program\" if it's not active yet Either: Scan the customer's QR code, OR Enter their wallet address manually Enter the amount of tokens to issue Click \"Mint Tokens\" and confirm in your wallet Tokens are instantly sent to the customer! ⚡"},{"id":"guide#240","source":"guide","title":"Step 4: Track Performance","text":"Use the Dashboard and CRM to analyze your program: Dashboard: See total customers, active users, tokens issued, and redemption rates Customers: View detailed profiles with purchase history and RFM segmentation Tiers: Set up Bronze/Silver/Gold/Platinum tiers with different benefits Marketing: Create targeted campaigns for different customer segments Automation: Set up automatic triggers for at-risk customers, tier upgrades, etc."},{"id":"guide#241","source":"guide","title":"Step 5: Redeem Customer Vouchers","text":"When a customer wants to use their reward voucher, you can quickly verify and redeem it: Go to the \"Rewards\" tab in your Merchant panel Find the \"Issued Vouchers\" section Click the \"Scan QR\" button to open the camera Scan the QR code shown on the customer's screen The voucher is found automatically — confirm by clicking \"Mark as Used\" Alternatively, search by voucher code manually in the search field QR scanning makes voucher redemption instant — no need to type long codes manually!"},{"id":"guide#242","source":"guide","title":"Merchant Pricing","text":"Starter • Active loyalty programs on Base • Customer profiles & basic analytics • Rewards catalog & vouchers • Branded B20 loyalty token Growth • RFM segmentation & enhanced analytics • Marketing campaigns & personalized offers • Team & branch management • AI automation rules + priority support Scale • Everything in Growth • Priority routing & SLA • Dedicated onboarding • Custom integrations & advanced reporting Paid in USDC on Base. Annual billing: 15–20% off. Full plan comparison on the Pricing page Click \"Sign In\" to get started. You can use email or passkey (no crypto knowledge needed), or connect an existing wallet like MetaMask or Coinbase Wallet."},{"id":"guide#243","source":"guide","title":"Step 1: Sign In","text":"Choose the sign-in method that works best for you: Email, Phone, or Google (recommended): Click \"Sign In\" via Privy. A secure wallet is created automatically — no crypto knowledge needed. Existing Wallet: Connect MetaMask, Coinbase Wallet, or WalletConnect if you already have one. Farcaster: If you're in Warpcast, your wallet connects automatically. No crypto experience needed! With email/passkey sign-in, a secure wallet is created for you behind the scenes."},{"id":"guide#244","source":"guide","title":"What is a Wallet Address?","text":"Your unique ID in the loyalty system A wallet address is your unique identifier in Loyal Spark — like an account number in a bank, but for loyalty tokens. It looks like a long string of letters and numbers starting with for example: How is it created? When you sign in with email, phone, or Google, a secure embedded wallet is created for you automatically by Privy. You don't need to install any apps or know anything about crypto — it just works. What is it used for? Your address is where merchants send loyalty tokens when you make a purchase. It's also encoded in the QR code that you show at checkout. Think of it as your \"loyalty card number\". Where can I see it? Your wallet address is displayed under the QR code in the Loyalty tab. You can also tap the copy button next to it to share it with a merchant directly. Is it safe to share? Yes! Your wallet address is like a public email address — anyone can send tokens to it, but only you can spend them. Sharing your address or QR code only allows others to send you tokens, not take anything from your wallet. Your wallet is secured by Privy. Your private keys are protected with multi-party computation (MPC) and trusted execution environments — no single party (including Privy or Loyal Spark) can access your funds without your authorization."},{"id":"guide#245","source":"guide","title":"Step 2: Earn Loyalty Tokens","text":"Sign in to Loyal Spark Navigate to the Customer section At the top you'll see \"Your QR Code\" card — tap it to enlarge Show the QR code to a participating merchant The merchant will scan your code and issue tokens to your wallet Tokens appear in the \"Your Loyalty Tokens\" section instantly! 💡 Pro Tip: You can also copy your wallet address using the \"Copy Address\" button below the QR code and share it directly with a merchant."},{"id":"guide#246","source":"guide","title":"Step 3: Redeem Rewards","text":"Browse the \"Rewards\" catalog in the Customer section Find a reward you want (check you have enough tokens) Click \"Activate Voucher\" Confirm the transaction in your wallet Your voucher will appear in \"My Vouchers\" with a QR code Show the QR code to the merchant — they can scan it instantly to redeem your voucher Alternatively, share the voucher code text and the merchant enters it manually Vouchers are unique to you and stored on the blockchain. Once activated, only you can use them!"},{"id":"guide#247","source":"guide","title":"Step 4: Level Up & Get More Perks","text":"Many loyalty programs have tier systems - earn more tokens to unlock better rewards: Bronze: Starting tier for new customers Silver: 1.25x cashback multiplier Gold: 1.5x cashback + exclusive offers Platinum: 2x cashback + VIP perks"},{"id":"guide#248","source":"guide","title":"Step 5: Invite Friends & Earn Bonuses","text":"Get bonus tokens when friends join via your referral code Many programs run a referral bonus — both you and the friend you invite receive extra tokens automatically when they make their first qualifying purchase. Open the Referrals section in the Customer panel Generate or copy your unique referral code (one per program) Share the code with friends — by message, link or QR When they sign up and use it, both wallets receive bonus tokens onchain Track your invited friends and total bonuses in the Referral Stats card AI agents can integrate with Loyal Spark via REST API or MCP Server to autonomously manage loyalty programs, mint tokens, and more."},{"id":"guide#249","source":"guide","title":"What Can AI Agents Do?","text":"Loyal Spark is an AI-native protocol. AI agents can perform the same operations as human merchants — creating programs, minting tokens, managing rewards — all programmatically through our API."},{"id":"guide#250","source":"guide","title":"REST API","text":"Full CRUD API with scoped permissions. Create programs, mint tokens, manage rewards, view analytics."},{"id":"guide#251","source":"guide","title":"MCP Server","text":"Connect Claude, GPT, Cursor, or any MCP-compatible LLM directly — no custom code needed."},{"id":"guide#252","source":"guide","title":"Server Wallets","text":"Coinbase CDP MPC wallets for autonomous onchain operations. No private keys to manage."},{"id":"guide#253","source":"guide","title":"Scoped Permissions","text":"Granular access control: read, mint, manage_rewards, create_program, trade."},{"id":"guide#254","source":"guide","title":"Step 1: Register an Agent","text":"Connect your wallet as a Merchant Go to the \"AI Agents\" tab in the Merchant Panel Click \"Register Agent\" Enter agent name and select permissions (scopes) Copy your API key ( lsk_... Use the key in the x-api-key header for all API calls"},{"id":"guide#255","source":"guide","title":"Step 2: Make API Calls","text":"Example REST API call: Or connect via MCP (for Claude, Cursor, etc.): \"mcpServers\": { \"loyal-spark\": { \"url\": \"https://api.loyalspark.online/loyalty-mcp\", \"headers\":"},{"id":"guide#256","source":"guide","title":"Pricing Plans","text":"Free • 1 agent (lsk_ or rwk_) • 200 API calls / month • 1,000 loyalty tokens minted / month • All MCP & REST endpoints • Mint fee 1.25% Pro • Up to 5 agents • 10,000 API calls / month • Mint fee 0.50% • CDP wallet provisioning • Priority MCP routing Enterprise • Unlimited agents • Unlimited API calls • Mint fee 0.25% • Dedicated routing & SLA • Priority support Subscriptions paid in USDC on Base ($1 = 1 USDC), verified onchain. The mint fee is separate and charged in your own loyalty tokens, not USDC. The token contract does not enforce it — the API tracks an off-chain obligation. See the full breakdown on the Pricing page"},{"id":"guide#257","source":"guide","title":"Recipient Agents (rwk_ keys)","text":"For agents that hold and spend tokens on behalf of a customer wallet If your agent only controls a customer wallet (not a merchant), use a rwk_ key instead of lsk_ . Recipient agents can: Read balances, vouchers and personalized offers Redeem rewards and accept P2P offers Prepare loyalty token transfer calldata for any address ( prepare_loyalty_token_transfer Create / cancel marketplace offers Endpoints: /recipient-api (REST) and /recipient-loyalty-mcp (MCP). Register via SIWE — see /for-agents"},{"id":"guide#258","source":"guide","title":"Resources","text":"API Documentation Interactive docs with examples Agent Skills 11 step-by-step guides for agents Agent Discovery agent.json protocol specification"},{"id":"guide#259","source":"guide","title":"Additional Resources","text":"Learn more about Web3 and blockchain technology MetaMask Guide Official MetaMask documentation Base Network Docs Learn about the Base blockchain Understanding Wallets Ethereum.org wallet guide Crypto Basics Coinbase Learn center"},{"id":"faq#260","source":"faq","title":"Blockchain & Web3 FAQ","text":"Common questions about blockchain loyalty tokens"},{"id":"faq#261","source":"faq","title":"What is blockchain?","text":"Blockchain is a digital ledger technology that records transactions across multiple computers. Think of it as a permanent, transparent record book that everyone can see but no one can alter. In Loyal Spark, the blockchain ensures all loyalty token transactions are transparent and verifiable."},{"id":"faq#262","source":"faq","title":"Do I need a crypto wallet?","text":"No! You can sign in with just your email, phone, or Google. A secure embedded wallet is created for you automatically behind the scenes via Privy (MPC-secured). If you already have a Web3 wallet (like MetaMask or Coinbase Wallet), you can use that too. Either way, you control your rewards directly."},{"id":"faq#263","source":"faq","title":"What are loyalty tokens?","text":"Loyalty tokens are digital rewards stored on the blockchain. Unlike traditional points that only exist in a company's database, these tokens sit in a wallet you control. You can hold them, trade them, or use them for rewards - and no one can take them away from you."},{"id":"faq#264","source":"faq","title":"Why use blockchain for loyalty?","text":"Blockchain provides several advantages: True ownership: You own your tokens, not the company Transparency: All transactions are visible and verifiable Transferable: Send tokens to another wallet or swap them via P2P escrow Security: Cryptographically secured and tamper-proof Interoperability: Use tokens across different platforms"},{"id":"faq#265","source":"faq","title":"How do I get started?","text":"For Customers: Click \"Sign In\" (use email, passkey, or an existing wallet) Choose \"I'm a Shopper\" Show your QR code to merchants to earn tokens Browse rewards and redeem with your tokens For Merchants: Sign in with email, passkey, or wallet Choose \"I'm a Business\" Create your loyalty program and deploy your token Scan customer QR codes to issue tokens"},{"id":"faq#266","source":"faq","title":"Is it safe and secure?","text":"Yes! Blockchain technology is extremely secure. Your tokens are protected by cryptography - the same technology that secures cryptocurrencies worth trillions of dollars. Only you have access to your wallet and tokens. However, remember: If using a traditional wallet, keep your password/seed phrase safe Never share your private keys with anyone Email, phone and Google sign-in accounts are secured by Privy embedded wallets (MPC)"},{"id":"faq#267","source":"faq","title":"Do I need to pay gas fees?","text":"For customers: No! All token transactions are sponsored by merchants. You don't need to pay anything to receive or redeem tokens. For merchants: Yes, there are small blockchain fees (gas fees) when you deploy your token contract and issue rewards. These fees go to the blockchain network, not to Loyal Spark. We use Base network which has very low fees (typically less than $0.01 per transaction)."},{"id":"faq#268","source":"faq","title":"What if the business closes?","text":"This is a key advantage of blockchain! Even if a business closes, your tokens still exist on the blockchain and remain in your wallet. While you may not be able to redeem them with that specific merchant anymore, you still own them and could potentially: Hold them in your wallet Send them to another address Use them if another business accepts them This is very different from traditional loyalty points which disappear when a company closes."},{"id":"faq#269","source":"faq","title":"Which blockchain network do you use?","text":"Production runs on Base mainnet (chain 8453). Base is an Ethereum Layer 2 network that offers: Very low transaction fees (typically under $0.01) Fast transaction speeds (1-2 seconds) Full Ethereum security and compatibility Backed by Coinbase"}];
